window.TREE={"subject":"Area II · Business Law","key":"reg_area2_business_law","brand":"Terra Prep","area":"II","law_asof":"2026-09-29","parts":[{"no":1,"name":"Area II · Business Law","chs":["1-01","1-02","1-03","1-04","1-05"],"color":"--fam-soc"}],"chs":[{"key":"1-01","part":1,"no":1,"name":"Agency","grp":"A","nodes":[1,2]},{"key":"1-02","part":1,"no":2,"name":"Contracts","grp":"B","nodes":[3,4,5]},{"key":"1-03","part":1,"no":3,"name":"Debtor-creditor relationships","grp":"C","nodes":[6]},{"key":"1-04","part":1,"no":4,"name":"Federal laws affecting business","grp":"D","nodes":[7,8,9,10,11]},{"key":"1-05","part":1,"no":5,"name":"Business structure","grp":"E","nodes":[12,13]}],"nodes":[{"no":1,"part":1,"ch":1,"title":"Agency: duties and liabilities of agents and principals","name":"Agency: duties and liabilities of agents and principals","vol":7,"q":7,"cs":0,"law":0,"grp":"A"},{"no":2,"part":1,"ch":1,"title":"Agency: authority of agents and principals","name":"Agency: authority of agents and principals","vol":2,"q":2,"cs":0,"law":0,"grp":"A"},{"no":3,"part":1,"ch":2,"title":"Contracts: formation","name":"Contracts: formation","vol":6,"q":6,"cs":0,"law":0,"grp":"B"},{"no":4,"part":1,"ch":2,"title":"Contracts: performance and discharge","name":"Contracts: performance and discharge","vol":5,"q":5,"cs":0,"law":0,"grp":"B"},{"no":5,"part":1,"ch":2,"title":"Contracts: breach and remedies","name":"Contracts: breach and remedies","vol":10,"q":10,"cs":0,"law":0,"grp":"B"},{"no":6,"part":1,"ch":3,"title":"Debtor-creditor relationships","name":"Debtor-creditor relationships","vol":23,"q":23,"cs":0,"law":0,"grp":"C"},{"no":7,"part":1,"ch":4,"title":"Federal laws: qualified health plans","name":"Federal laws: qualified health plans","vol":6,"q":6,"cs":0,"law":0,"grp":"D"},{"no":8,"part":1,"ch":4,"title":"Federal laws: worker classification","name":"Federal laws: worker classification","vol":2,"q":2,"cs":0,"law":0,"grp":"D"},{"no":9,"part":1,"ch":4,"title":"Federal laws: bankruptcy","name":"Federal laws: bankruptcy","vol":9,"q":9,"cs":0,"law":0,"grp":"D"},{"no":10,"part":1,"ch":4,"title":"Federal laws: anti-bribery (FCPA)","name":"Federal laws: anti-bribery (FCPA)","vol":5,"q":5,"cs":0,"law":0,"grp":"D"},{"no":11,"part":1,"ch":4,"title":"Federal laws: employment taxes","name":"Federal laws: employment taxes","vol":6,"q":6,"cs":0,"law":0,"grp":"D"},{"no":12,"part":1,"ch":5,"title":"Business structure: selection, formation, operation and termination","name":"Business structure: selection, formation, operation and termination","vol":6,"q":6,"cs":0,"law":0,"grp":"E"},{"no":13,"part":1,"ch":5,"title":"Business structure: rights, duties and authority of owners and management","name":"Business structure: rights, duties and authority of owners and management","vol":15,"q":15,"cs":0,"law":0,"grp":"E"}],"stat":{"parts":1,"chs":5,"nodes":13,"q":102}};
window.QBANK={"1":[{"i":"REG-II-A-0005","t":"Nell is the treasurer of Orchard Supply Inc. and is authorized to sign its checks. She signed a $6,400 check payable to a vendor with the signature block reading \"Orchard Supply Inc., by Nell Ruiz, Treasurer.\" The company's account was later closed, and the check was dishonored. The vendor sued Nell personally on the check. Which statement is most accurate?","mc":{"s":"Nell is the treasurer of Orchard Supply Inc. and is authorized to sign its checks. She signed a $6,400 check payable to a vendor with the signature block reading \"Orchard Supply Inc., by Nell Ruiz, Treasurer.\" The company's account was later closed, and the check was dishonored. The vendor sued Nell personally on the check. Which statement is most accurate?","d":"","o":["Nell is personally liable, because anyone who signs a check as a representative guarantees that the bank will pay it.","Nell is personally liable, because the check would bind the company only if Nell had also signed her own name as a separate guarantor.","Nell is personally liable unless the vendor agreed in writing to look only to Orchard Supply Inc. for payment.","Nell is not personally liable, because the form of the signature shows clearly that she signed for the company named on the check."],"a":4,"cite":"UCC §3-402(b)(1)","rat":"When an authorized representative signs so that the form of the signature shows unambiguously that it is made for an identified represented person, the representative is not liable on the instrument.","ex":["A representative does not guarantee payment merely by signing as a representative. Personal liability depends on how the signature reads.","An authorized signature made in a clear representative form binds the company without any separate guaranty by the signer.","No separate agreement is needed when the signature shows unambiguously that it was made for the identified company.","When an authorized representative signs so that the form of the signature shows unambiguously that it is made for an identified represented person, the representative is not liable on the instrument. The company is the obligor."],"wt":["concept","concept","concept",""],"tags":{"area":"II","group":"A","skill":"Application","diff":1},"asof":"2026-09-29","rl":"An authorized representative who signs in a form clearly showing the represented company is not personally liable on the instrument."}},{"i":"REG-II-A-0006","t":"Omar manages Delta Carpets LLC and has authority to sign its notes. To buy inventory he signed a $30,000 promissory note in the maker's block with only \"Omar Ansel.\" The note did not mention Delta Carpets LLC anywhere. The seller negotiated the note to Fenwick Bank, a holder in due course that took it without notice that Omar was not meant to be liable. The note went unpaid, and Fenwick Bank sued Omar. Which statement is most accurate?","mc":{"s":"Omar manages Delta Carpets LLC and has authority to sign its notes. To buy inventory he signed a $30,000 promissory note in the maker's block with only \"Omar Ansel.\" The note did not mention Delta Carpets LLC anywhere. The seller negotiated the note to Fenwick Bank, a holder in due course that took it without notice that Omar was not meant to be liable. The note went unpaid, and Fenwick Bank sued Omar. Which statement is most accurate?","d":"","o":["Omar is not liable, because an agent with authority to sign binds only the principal, whatever form the signature takes, so the bank must look to the company.","Omar is liable only if Fenwick Bank proves that Omar personally intended to be bound on the note.","Omar is liable to Fenwick Bank, because his signature does not show a representative capacity and the company is not identified on the note.","Omar is liable only for half of the note, sharing liability equally with Delta Carpets LLC as co-obligors on the instrument held by the bank after the negotiation."],"a":3,"cite":"UCC §3-402(a), (b)(2)","rat":"Where the signature form does not show a representative capacity and the represented person is not identified, the representative is liable to a holder in due course that took without notice that the representative was not to be liable.","ex":["The company may be bound, but the form of the signature can also make the representative liable to a holder in due course.","That burden allocation applies to other parties. A holder in due course without notice does not have to prove the signer's intent.","Where the signature form does not show a representative capacity and the represented person is not identified, the representative is liable to a holder in due course that took without notice that the representative was not to be liable.","The rules do not split the debt in half. The representative can be liable on the whole instrument."],"wt":["concept","concept","","concept"],"tags":{"area":"II","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A representative whose signature shows no representative capacity or represented person is liable to a holder in due course without notice."}},{"i":"REG-II-A-0013","t":"Nora paid a $9,000 deposit for a custom cabinet order at the shop of Bright Cabinetry, a general partnership. Wade, one of the partners, accepted her check, gave her a partnership receipt and then deposited the check into his personal account and spent the money. The partnership never built the cabinet. Nora sued the partnership for the $9,000. Which statement is most accurate?","mc":{"s":"Nora paid a $9,000 deposit for a custom cabinet order at the shop of Bright Cabinetry, a general partnership. Wade, one of the partners, accepted her check, gave her a partnership receipt and then deposited the check into his personal account and spent the money. The partnership never built the cabinet. Nora sued the partnership for the $9,000. Which statement is most accurate?","d":"","o":["The partnership is not liable, because Wade acted for himself when he spent the money, so only Wade is responsible for the loss.","The partnership is liable only if the other partners knew about Wade's plan to keep the deposit and approved it before he spent the money.","The partnership is liable only for the profit it would have earned on the cabinet, because a deposit is not property of the customer.","The partnership is liable for the loss, because Wade received the money in the course of its business and a partner misapplied it."],"a":4,"cite":"RUPA (1997, amended 2013) §305(b)","rat":"A partnership is liable for the loss when a partner, acting in the partnership's business or with actual or apparent authority, receives money of a non-partner and a partner misapplies it.","ex":["The misapplication by a partner does not release the partnership when the partner received the money in the course of the partnership's business.","The partnership's liability does not depend on the other partners' knowledge or approval of the misapplication.","The rule covers the loss of the money or property received, not just lost profit, and a customer's deposit is money of a non-partner.","A partnership is liable for the loss when a partner, acting in the partnership's business or with actual or apparent authority, receives money of a non-partner and a partner misapplies it."],"wt":["concept","concept","concept",""],"tags":{"area":"II","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A partnership is liable when a partner misapplies money of a non-partner received in the partnership's business."}},{"i":"REG-II-A-0014","t":"Ines is one of three partners in Cobb Realty, a general partnership. While the partnership was negotiating to buy an office building, Ines learned that the seller knew of a serious foundation defect. The seller had secretly paid Ines $20,000 to say nothing to the other partners, and she did not. The partnership bought the building for $900,000 and later sued the seller for concealing the defect. The seller argues that the partnership knew of the defect because Ines knew. Which statement is most accurate?","mc":{"s":"Ines is one of three partners in Cobb Realty, a general partnership. While the partnership was negotiating to buy an office building, Ines learned that the seller knew of a serious foundation defect. The seller had secretly paid Ines $20,000 to say nothing to the other partners, and she did not. The partnership bought the building for $900,000 and later sued the seller for concealing the defect. The seller argues that the partnership knew of the defect because Ines knew. Which statement is most accurate?","d":"","o":["The partnership is treated as knowing of the defect, because a partner's knowledge of a fact relating to the partnership is imputed to the partnership in all circumstances.","The partnership is not treated as knowing of the defect through Ines, because a partner's knowledge is not imputed when the partner commits a fraud on the partnership.","The partnership is treated as knowing of the defect only after the other two partners are told of it in a signed writing.","The partnership is treated as knowing of the defect unless the partnership agreement expressly excludes imputation of partner knowledge."],"a":2,"cite":"RUPA (1997, amended 2013) §103(e)","rat":"A partner's knowledge of a partnership-related fact is effective immediately as knowledge of the partnership, except in the case of a fraud on the partnership committed by or with the consent of that partner.","ex":["Imputation of a partner's knowledge has an exception for a fraud on the partnership committed by or with the consent of that partner.","A partner's knowledge of a partnership-related fact is effective immediately as knowledge of the partnership, except in the case of a fraud on the partnership committed by or with the consent of that partner. Ines's secret payment makes the exception apply.","Imputation is immediate when it applies. No writing or telling of the other partners is required.","The fraud exception applies by statute in this situation. It does not depend on a term in the partnership agreement."],"wt":["concept","","concept","concept"],"tags":{"area":"II","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A partner's knowledge is not imputed to the partnership when the partner commits or consents to a fraud on the partnership."}},{"i":"REG-II-A-0016","t":"Hale and Reed is a general partnership that is not a limited liability partnership. In March it bought $50,000 of supplies on credit from Grant Supply and did not pay. In June Tanya was admitted as a new partner and contributed $30,000 of capital to the firm. In September Grant Supply sued the partnership and Tanya for the March debt. Which statement is most accurate about Tanya?","mc":{"s":"Hale and Reed is a general partnership that is not a limited liability partnership. In March it bought $50,000 of supplies on credit from Grant Supply and did not pay. In June Tanya was admitted as a new partner and contributed $30,000 of capital to the firm. In September Grant Supply sued the partnership and Tanya for the March debt. Which statement is most accurate about Tanya?","d":"","o":["Tanya is jointly and severally liable for the March debt with the other partners, because all partners are liable for all partnership debts at the time of suit.","Tanya is personally liable for half of the March debt, because she was admitted before Grant Supply filed suit.","Tanya is personally liable only if she knew of the March debt when she was admitted as a partner.","Tanya is not personally liable for the March debt, although the partnership's assets, including her contribution, remain available to the creditor."],"a":4,"cite":"RUPA (1997, amended 2013) §306(a), (b)","rat":"A person who becomes a partner is not personally liable for a partnership obligation incurred before becoming a partner.","ex":["A partner is jointly and severally liable for obligations of the partnership generally, but a new partner is not personally liable for those incurred before admission.","The rule does not divide the earlier debt. The timing of the suit does not change the exemption for pre-admission obligations.","Her knowledge does not matter. The rule protects a new partner from personal liability for pre-admission obligations.","A person who becomes a partner is not personally liable for a partnership obligation incurred before becoming a partner. The partnership's own assets still answer for the debt."],"wt":["concept","concept","concept",""],"tags":{"area":"II","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A new partner is not personally liable for pre-admission partnership obligations, though partnership assets remain liable."}},{"i":"REG-II-A-0017","t":"Rana withdrew from Westside Movers, a general partnership, on January 10, 2026. She gave no notice to customers or suppliers, and no statement of dissociation was filed. On March 5, 2026 the partnership bought $18,000 of equipment on credit from Fern Co., which had dealt with Rana as a partner in the past. Fern Co. did not know she had left and reasonably believed she was still a partner. The partnership did not pay. Which statement is most accurate about Rana's liability to Fern Co.?","mc":{"s":"Rana withdrew from Westside Movers, a general partnership, on January 10, 2026. She gave no notice to customers or suppliers, and no statement of dissociation was filed. On March 5, 2026 the partnership bought $18,000 of equipment on credit from Fern Co., which had dealt with Rana as a partner in the past. Fern Co. did not know she had left and reasonably believed she was still a partner. The partnership did not pay. Which statement is most accurate about Rana's liability to Fern Co.?","d":"","o":["Rana can be liable, because under two years had passed and Fern Co. lacked notice and reasonably believed she was a partner.","Rana is not liable, because a person who has dissociated as a partner cannot be liable for obligations incurred after leaving.","Rana is liable only for obligations incurred within 90 days after she withdrew, because after 90 days everyone is deemed to have notice.","Rana is liable only if Fern Co. proves that Rana was told about the purchase before it happened."],"a":1,"cite":"RUPA (1997, amended 2013) §703(a), (b); RUPA (1997, amended 2013) §103(d)(2)(A)","rat":"A person who has dissociated as a partner can be liable on a later partnership transaction if a partner would be liable and, when the other party enters into it, less than two years have passed and the party lacks knowledge or notice and reasonably believes the person is a partner.","ex":["A person who has dissociated as a partner can be liable on a later partnership transaction if a partner would be liable and, when the other party enters into it, less than two years have passed and the party lacks knowledge or notice and reasonably believes the person is a partner.","There is a limited exception that keeps a dissociated person liable to a person who reasonably relies on her apparent partner status.","The 90-day notice rule applies only after a statement of dissociation becomes effective, and none was filed. The outer limit here is two years.","Her knowledge of the purchase is not an element. The test looks at what the other party knew and reasonably believed."],"wt":["","concept","limit","concept"],"tags":{"area":"II","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A dissociated partner can remain liable for up to two years to a third party who lacked notice and reasonably believed she was a partner."}},{"i":"REG-II-A-0018","t":"Kip is an office clerk at Dune Realty Inc. and has no authority to sign checks. He signed the name of the company's president on a $7,500 check payable to Metro Tile, in payment of a real debt the company owed for tile. When the president learned of it, she told Metro Tile that the company approved the payment and would stand behind the check. Is Dune Realty bound on the check?","mc":{"s":"Kip is an office clerk at Dune Realty Inc. and has no authority to sign checks. He signed the name of the company's president on a $7,500 check payable to Metro Tile, in payment of a real debt the company owed for tile. When the president learned of it, she told Metro Tile that the company approved the payment and would stand behind the check. Is Dune Realty bound on the check?","d":"","o":["Yes, because an unauthorized signature may be ratified, and the president's approval ratified this signature.","No, because a signature made without authority cannot become effective as the signature of the person whose name was signed.","No, because ratification is effective only if it is made in a signed writing delivered to the bank on which the check is drawn.","Yes, but only because Kip, as an employee, was entitled to sign for the company in ordinary matters like paying a tile bill."],"a":1,"cite":"UCC §3-403(a)","rat":"An unauthorized signature is ineffective as the signature of the person whose name was signed unless it is ratified.","ex":["An unauthorized signature is ineffective as the signature of the person whose name was signed unless it is ratified. It may be ratified for all purposes.","The rule allows ratification of an unauthorized signature.","The statute does not require a signed writing delivered to the drawee bank for ratification.","Kip had no authority. The company is bound by ratification, not by authority he did not have."],"wt":["","concept","concept","concept"],"tags":{"area":"II","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"An unauthorized signature may be ratified, binding the principal without a formal writing to the bank."}}],"2":[{"i":"REG-II-A-0007","t":"Three partners operate Ridge Print, a general partnership that does commercial printing. Without asking the others, partner Yuri signed a contract in the partnership's name to sell the partnership's main printing press to Brant Co. for $80,000. A sale of its main equipment is not apparently part of carrying on the partnership's ordinary business. Brant Co. did not ask whether the other partners agreed. Is the partnership bound by the contract?","mc":{"s":"Three partners operate Ridge Print, a general partnership that does commercial printing. Without asking the others, partner Yuri signed a contract in the partnership's name to sell the partnership's main printing press to Brant Co. for $80,000. A sale of its main equipment is not apparently part of carrying on the partnership's ordinary business. Brant Co. did not ask whether the other partners agreed. Is the partnership bound by the contract?","d":"","o":["No, because the sale was not apparently in the ordinary course, so it binds the partnership only if all the other partners actually authorized it.","Yes, because each partner is an agent of the partnership and can bind it in any matter, ordinary or not.","Yes, because Brant Co. had no notice of any limit on Yuri's authority when it signed the contract and relied on his signature in the partnership's name.","No, because only a majority of the partners can bind the partnership, and Yuri alone is not a majority."],"a":1,"cite":"RUPA (1997, amended 2013) §301(1), (2)","rat":"A partner's act that is not apparently for carrying on the ordinary course of the business binds the partnership only if all the other partners actually authorized it.","ex":["A partner's act that is not apparently for carrying on the ordinary course of the business binds the partnership only if all the other partners actually authorized it.","A partner's apparent authority covers acts apparently carrying on ordinary business, not every act.","Lack of notice matters for ordinary-course acts. For an act outside the ordinary course, actual authorization from all the other partners is needed.","A majority decides ordinary matters among the partners, but an act outside the ordinary course needs all the other partners' actual authorization."],"wt":["","concept","concept","concept"],"tags":{"area":"II","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A partner's act outside the apparent ordinary course binds the partnership only if all other partners actually authorized it."}},{"i":"REG-II-A-0015","t":"Marlow and Sons is a general partnership owned by two brothers. At a bank's business luncheon the brothers introduced Doyle to the guests as \"our new partner,\" and Doyle, who is not a partner and has no interest in the firm, said nothing. Evans Supply was at the luncheon, relied on the introduction and sold $30,000 of goods on credit to the firm. The firm did not pay. Evans sued Doyle. Which statement is most accurate?","mc":{"s":"Marlow and Sons is a general partnership owned by two brothers. At a bank's business luncheon the brothers introduced Doyle to the guests as \"our new partner,\" and Doyle, who is not a partner and has no interest in the firm, said nothing. Evans Supply was at the luncheon, relied on the introduction and sold $30,000 of goods on credit to the firm. The firm did not pay. Evans sued Doyle. Which statement is most accurate?","d":"","o":["Doyle can be liable to Evans, because he consented to being represented as a partner and Evans relied on that.","Doyle is not liable, because only a person who signed a partnership agreement can be responsible for debts of the partnership.","Doyle is liable only if he received part of the goods that Evans delivered to the firm.","Doyle is liable only if he had also shared in the firm's profits before the luncheon took place."],"a":1,"cite":"RUPA (1997, amended 2013) §308(a)","rat":"A person who consents to being represented as a partner is liable to a person who relies on the representation and enters into a transaction with the actual or purported partnership.","ex":["A person who consents to being represented as a partner is liable to a person who relies on the representation and enters into a transaction with the actual or purported partnership.","Liability of a purported partner arises from the representation and reliance, not from a signed agreement.","Receiving a benefit is not required for a purported partner's liability.","Sharing profits is a test for whether a person is a partner in fact. A purported partner can be liable without being one."],"wt":["","concept","concept","concept"],"tags":{"area":"II","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A person who consents to being represented as a partner is liable to those who rely on the representation."}}],"3":[{"i":"REG-II-B-0001","t":"On April 1, Marla, who owns a hardware store, signed and mailed a letter offering to sell Tom 200 ladders at $40 each. The letter said the offer would stay open for 30 days. Tom paid nothing for that assurance. On April 10, Marla wrote that she was withdrawing the offer. On April 15, Tom accepted in writing. Which statement is most accurate?","mc":{"s":"On April 1, Marla, who owns a hardware store, signed and mailed a letter offering to sell Tom 200 ladders at $40 each. The letter said the offer would stay open for 30 days. Tom paid nothing for that assurance. On April 10, Marla wrote that she was withdrawing the offer. On April 15, Tom accepted in writing. Which statement is most accurate?","d":"","o":["No contract was formed, because a promise to keep an offer open is unenforceable without consideration from the offeree.","No contract was formed, because a firm offer for goods cannot stay open for longer than 10 days.","No contract was formed, because Tom had to pay at least a nominal amount to hold the offer open.","A contract was likely formed, because Marla's signed writing held the offer open without consideration."],"a":4,"cite":"UCC §2-205","rat":"Marla is a merchant, the assurance is in a signed writing, and 30 days is within the three-month maximum, so the April 10 withdrawal did not end the offer.","ex":["That is the common-law rule. For goods, a merchant's signed firm offer needs no consideration.","The statutory maximum for a firm offer is three months, not 10 days.","Payment is unnecessary. A signed writing by a merchant takes the place of consideration.","Marla is a merchant, the assurance is in a signed writing, and 30 days is within the three-month maximum, so the April 10 withdrawal did not end the offer."],"wt":["concept","limit","concept",""],"tags":{"area":"II","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A merchant's signed firm offer for goods needs no consideration and stays open for the stated time, up to three months."}},{"i":"REG-II-B-0002","t":"Priya orally agreed to buy a used commercial oven from Lee, a restaurant-equipment dealer, for $2,400. Lee signed nothing, Priya paid no deposit, no oven was delivered, and Lee never admitted the deal in court or in writing. Lee later refused to sell, and Priya sued. Which statement is most accurate?","mc":{"s":"Priya orally agreed to buy a used commercial oven from Lee, a restaurant-equipment dealer, for $2,400. Lee signed nothing, Priya paid no deposit, no oven was delivered, and Lee never admitted the deal in court or in writing. Lee later refused to sell, and Priya sued. Which statement is most accurate?","d":"","o":["Priya will likely win, because an oral contract for the sale of goods is enforceable whatever the price.","Priya will likely win, because Lee is a merchant and a merchant's oral promise is enough to bind the merchant to sell.","Priya will likely lose, because a $2,400 sale of goods needs a writing signed by Lee and no exception applies.","Priya will likely lose, because an oral contract for goods is void even after part payment or delivery."],"a":3,"cite":"UCC §2-201(1)","rat":"The price exceeds $500, Lee signed nothing, and there was no part payment, delivery, admission or special manufacture that would supply an exception.","ex":["The sales statute of frauds requires a signed writing for goods of $500 or more, subject to exceptions.","The merchant exception depends on a written confirmation that was sent and not objected to, and none exists here.","The price exceeds $500, Lee signed nothing, and there was no part payment, delivery, admission or special manufacture that would supply an exception.","Oral sales contracts can be enforced when an exception applies, such as part payment or acceptance of delivery."],"wt":["concept","concept","","concept"],"tags":{"area":"II","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A sale of goods for $500 or more needs a writing signed by the party to be charged unless an exception applies."}},{"i":"REG-II-B-0003","t":"Bao Co. signed a contract to sell Rey Inc. 500 units at $20 each. Before delivery, Bao said its supplier's costs had risen and asked for $22 per unit. Rey agreed in a signed writing and gave nothing new in return. Bao delivered, and Rey paid only $20 per unit, arguing the increase lacked consideration. Which statement is most accurate?","mc":{"s":"Bao Co. signed a contract to sell Rey Inc. 500 units at $20 each. Before delivery, Bao said its supplier's costs had risen and asked for $22 per unit. Rey agreed in a signed writing and gave nothing new in return. Bao delivered, and Rey paid only $20 per unit, arguing the increase lacked consideration. Which statement is most accurate?","d":"","o":["Rey wins, because the pre-existing duty rule makes a price increase for goods unenforceable without new consideration.","Rey wins, because a signed contract for goods cannot be changed once both parties have signed it.","Bao wins only if it also delivered additional goods to Rey in exchange for the higher price.","The increase is likely binding, because a good-faith modification of a sales contract needs no new consideration."],"a":4,"cite":"UCC §2-209(1)","rat":"Article 2 dispenses with consideration for modifications.","ex":["The pre-existing duty rule is common law. Article 2 replaces it for sales of goods.","Parties may modify a sales contract. There is no bar on price changes after signing.","Additional goods are not required for the modification to bind.","Article 2 dispenses with consideration for modifications. The change must still be made in good faith, which these facts suggest."],"wt":["concept","concept","concept",""],"tags":{"area":"II","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Under UCC Article 2, a good-faith modification of a sales contract needs no new consideration."}},{"i":"REG-II-B-0012","t":"On March 1, Kite Foods, a food distributor, e-mailed Bard Bakery a purchase order for 2,000 pounds of flour at $0.50 per pound. The order stated that it limited acceptance to the terms of the order. Bard Bakery, also a merchant, returned a signed acknowledgment confirming the same goods and price but adding an arbitration clause. The acknowledgment was not made conditional on Kite Foods' agreeing to the clause. Kite Foods did not respond. Which statement is most accurate?","mc":{"s":"On March 1, Kite Foods, a food distributor, e-mailed Bard Bakery a purchase order for 2,000 pounds of flour at $0.50 per pound. The order stated that it limited acceptance to the terms of the order. Bard Bakery, also a merchant, returned a signed acknowledgment confirming the same goods and price but adding an arbitration clause. The acknowledgment was not made conditional on Kite Foods' agreeing to the clause. Kite Foods did not respond. Which statement is most accurate?","d":"","o":["No contract was formed, because the acknowledgment did not match the purchase order exactly.","A contract was formed that includes the arbitration clause, because between merchants silence in response to added terms is acceptance of any added term.","A contract was formed that includes the clause, because an arbitration clause cannot materially alter a contract between two merchants.","A contract was formed on the terms of the order, and the arbitration clause did not become part of it because the offer limited acceptance to its own terms."],"a":4,"cite":"UCC §2-207(1), (2)","rat":"A definite acceptance forms a contract despite added terms.","ex":["A definite and seasonable acceptance operates as an acceptance even though it adds terms, unless it is expressly conditional on the added terms.","Added terms do not enter the contract if the offer limited acceptance to its own terms, so silence does not add them.","Whether the clause materially alters the contract is beside the point here, because the offer had already barred added terms.","A definite acceptance forms a contract despite added terms. Between merchants the added terms are only proposals, and they do not become part of the contract where the offer expressly limits acceptance to its terms."],"wt":["concept","concept","concept",""],"tags":{"area":"II","group":"B","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"If an offer expressly limits acceptance to its terms, added terms in the acceptance do not become part of the contract."}},{"i":"REG-II-B-0025","t":"Kessler Bakery and Argo Supply signed a written contract for 1,000 pounds of flour at $0.60 per pound. The contract said, \"This writing is the complete and exclusive statement of the parties' agreement.\" Before signing, Argo's salesperson had orally promised free delivery within 24 hours. Argo delivered on the third day. Kessler wants to offer evidence of the oral promise to prove a breach. Which statement is most accurate?","mc":{"s":"Kessler Bakery and Argo Supply signed a written contract for 1,000 pounds of flour at $0.60 per pound. The contract said, \"This writing is the complete and exclusive statement of the parties' agreement.\" Before signing, Argo's salesperson had orally promised free delivery within 24 hours. Argo delivered on the third day. Kessler wants to offer evidence of the oral promise to prove a breach. Which statement is most accurate?","d":"","o":["The evidence is admissible, because a sales contract may be supplemented by any oral promise made before it was signed.","The evidence is not admissible to add the promise, because the writing is stated to be complete and exclusive.","The evidence is admissible, because a consistent additional term can be proved even when the writing says it is complete and exclusive.","The evidence is admissible only if Argo's salesperson later confirms the promise in a signed writing."],"a":2,"cite":"UCC §2-202","rat":"A writing intended as the final expression of the terms cannot be contradicted by prior agreements.","ex":["A prior oral promise cannot supplement a writing intended as a complete and exclusive statement of the terms.","A writing intended as the final expression of the terms cannot be contradicted by prior agreements. Evidence of consistent additional terms is excluded when the writing is intended as a complete and exclusive statement.","The consistent additional terms exception does not apply when the writing is intended as a complete and exclusive statement.","A later confirmation is not the test. The prior oral promise is excluded because of the integrated writing."],"wt":["concept","","concept","concept"],"tags":{"area":"II","group":"B","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"A prior oral promise cannot supplement a writing intended as a complete and exclusive statement of terms."}},{"i":"REG-II-B-0026","t":"On June 1, Hollis Stores, a retailer, sent a purchase order to Petra Pottery, a manufacturer, for 200 blue mugs at $6 each, for prompt shipment. On June 3, Petra shipped 200 green mugs instead, with a note saying the green mugs were sent only as an accommodation because blue mugs were out of stock. Hollis kept the green mugs unused and, on June 10, told Petra it would not pay the contract price. Which statement is most accurate?","mc":{"s":"On June 1, Hollis Stores, a retailer, sent a purchase order to Petra Pottery, a manufacturer, for 200 blue mugs at $6 each, for prompt shipment. On June 3, Petra shipped 200 green mugs instead, with a note saying the green mugs were sent only as an accommodation because blue mugs were out of stock. Hollis kept the green mugs unused and, on June 10, told Petra it would not pay the contract price. Which statement is most accurate?","d":"","o":["Petra's shipment was not an acceptance, because Petra promptly said the nonconforming goods were sent only as an accommodation.","Petra's shipment was an acceptance, and Hollis is bound to pay $6 each, because any shipment in response to an order is an acceptance.","Petra's shipment was an acceptance, and Petra is in breach only if Hollis rejects the goods within 24 hours.","Petra's shipment was not an acceptance, because an order for prompt shipment can be accepted only by a prompt written promise to ship."],"a":1,"cite":"UCC §2-206(1)(b)","rat":"An order for prompt shipment can be accepted by shipment of conforming or nonconforming goods.","ex":["An order for prompt shipment can be accepted by shipment of conforming or nonconforming goods. Shipment of nonconforming goods is not an acceptance if the seller seasonably notifies the buyer that it is offered only as an accommodation.","Shipment of nonconforming goods is an acceptance and also a breach, except where the seller seasonably notifies that it is an accommodation.","There is no 24-hour rule. The accommodation notice prevents the shipment from being an acceptance at all.","An order for prompt shipment invites acceptance either by a prompt promise or by prompt shipment."],"wt":["","concept","limit","concept"],"tags":{"area":"II","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Shipping nonconforming goods as an accommodation with prompt notice is a counteroffer, not an acceptance."}}],"4":[{"i":"REG-II-B-0004","t":"Nadia ordered 100 identical lamps under a one-time contract that was not an installment contract and did not limit her remedies. The seller delivered all 100 on time, but 3 lamps had cracked bases. Nadia wants to reject the whole delivery. Which statement is most accurate?","mc":{"s":"Nadia ordered 100 identical lamps under a one-time contract that was not an installment contract and did not limit her remedies. The seller delivered all 100 on time, but 3 lamps had cracked bases. Nadia wants to reject the whole delivery. Which statement is most accurate?","d":"","o":["Nadia may reject all 100, accept all 100, or keep some commercial units and reject the rest, subject to cure.","Nadia must keep all 100 lamps and may only sue the seller for damages for the 3 lamps with cracked bases.","Nadia may reject only the 3 cracked lamps and must keep the other 97 lamps that were delivered to her.","Nadia's rejection of the delivery is invalid, because fewer than 5 percent of the lamps were defective."],"a":1,"cite":"UCC §2-601","rat":"This describes the buyer's options when delivered goods fail to conform to the contract.","ex":["This describes the buyer's options when delivered goods fail to conform to the contract.","A buyer facing nonconforming goods may reject them. Acceptance is not forced.","Rejecting only the defective units is one option, not the only one. She may also reject the whole.","There is no 5 percent rule. A substantial-impairment test applies to installment contracts, which this is not."],"wt":["","concept","concept","limit"],"tags":{"area":"II","group":"B","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"In a single nonconforming delivery, the buyer may reject all, accept all, or accept some commercial units and reject the rest."}},{"i":"REG-II-B-0015","t":"Sol Co. agreed to deliver 10 machines to Vega Inc. in installments over six months, with payment due on each delivery. After the first delivery, Sol Co. learned from a trade report that Vega Inc. had missed payments to several other suppliers. Sol Co. sent Vega Inc. a written demand for assurance that Vega would pay for future deliveries. Which statement is most accurate?","mc":{"s":"Sol Co. agreed to deliver 10 machines to Vega Inc. in installments over six months, with payment due on each delivery. After the first delivery, Sol Co. learned from a trade report that Vega Inc. had missed payments to several other suppliers. Sol Co. sent Vega Inc. a written demand for assurance that Vega would pay for future deliveries. Which statement is most accurate?","d":"","o":["Sol Co. must keep delivering, because a contract cannot be suspended on the basis of a buyer's dealings with other suppliers.","Sol Co. may treat the contract as repudiated at once, without waiting for any response to its demand for assurance.","Sol Co. may suspend delivery only after a court finds that Vega Inc. is insolvent.","Sol Co. may, if commercially reasonable, suspend further deliveries until it receives adequate assurance of performance."],"a":4,"cite":"UCC §2-609(1), (4)","rat":"When reasonable grounds for insecurity arise, a party may demand adequate assurance in writing and, if commercially reasonable, suspend its own performance until it receives it.","ex":["Reasonable grounds for insecurity can arise from a buyer's conduct with others, and they let the seller demand assurance.","Failure to give adequate assurance within a reasonable time, not over thirty days, is what counts as repudiation.","The right to suspend does not depend on a court finding of insolvency.","When reasonable grounds for insecurity arise, a party may demand adequate assurance in writing and, if commercially reasonable, suspend its own performance until it receives it."],"wt":["concept","limit","concept",""],"tags":{"area":"II","group":"B","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A seller with reasonable grounds for insecurity may demand adequate assurance and suspend performance until received."}},{"i":"REG-II-B-0016","t":"On May 5, Tarn Co. agreed in writing to deliver 200 red widgets to Ives Inc. by May 30. On May 20, Tarn Co. delivered 200 blue widgets, and Ives Inc. rejected them that day. On May 22, Tarn Co. notified Ives Inc. that it would deliver red widgets, and it delivered 200 red widgets on May 28. Ives Inc. refused them, claiming that its rejection ended the contract. Which statement is most accurate?","mc":{"s":"On May 5, Tarn Co. agreed in writing to deliver 200 red widgets to Ives Inc. by May 30. On May 20, Tarn Co. delivered 200 blue widgets, and Ives Inc. rejected them that day. On May 22, Tarn Co. notified Ives Inc. that it would deliver red widgets, and it delivered 200 red widgets on May 28. Ives Inc. refused them, claiming that its rejection ended the contract. Which statement is most accurate?","d":"","o":["Ives Inc. must take the red widgets, because Tarn Co. gave timely notice of its intent to cure and made a conforming delivery within the contract time.","Ives Inc. may refuse them, because a rejection of a nonconforming delivery ends the contract and the seller cannot undo it.","Ives Inc. may refuse them, because cure is allowed only if the buyer agrees to it in writing before the seller redelivers.","Ives Inc. may refuse them, because cure is allowed only after the contract time for performance has expired."],"a":1,"cite":"UCC §2-508(1)","rat":"If the time for performance has not expired, a seller whose tender was rejected as nonconforming may seasonably notify the buyer of intent to cure and then make a conforming delivery within the contract time.","ex":["If the time for performance has not expired, a seller whose tender was rejected as nonconforming may seasonably notify the buyer of intent to cure and then make a conforming delivery within the contract time.","The right to cure exists precisely so that a rejected seller can still perform within the time allowed.","Cure does not depend on the buyer's consent. It depends on timely notice and delivery within the contract time.","The rule works the other way. Cure within the contract time is available while time remains."],"wt":["","concept","concept","concept"],"tags":{"area":"II","group":"B","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"A seller who gives timely notice may cure a nonconforming tender by delivering conforming goods within the contract time."}},{"i":"REG-II-B-0019","t":"Oren Farms, a merchant, agreed to sell Bell Diner 40 cases of specialty flour for $2,000. The contract required Oren to ship the flour by carrier but did not require delivery at any particular destination and said nothing about risk of loss. On May 3 Oren properly delivered the flour to a carrier. On May 4 a highway accident destroyed the shipment. Neither party was at fault. Which statement is most accurate?","mc":{"s":"Oren Farms, a merchant, agreed to sell Bell Diner 40 cases of specialty flour for $2,000. The contract required Oren to ship the flour by carrier but did not require delivery at any particular destination and said nothing about risk of loss. On May 3 Oren properly delivered the flour to a carrier. On May 4 a highway accident destroyed the shipment. Neither party was at fault. Which statement is most accurate?","d":"","o":["Bell Diner bears the loss and owes the price, because risk passed on delivery to the carrier.","Oren bears the loss, because risk of loss stays with a merchant seller until the buyer physically receives the goods.","Oren and Bell Diner share the loss equally, because neither party was at fault for the accident.","Oren bears the loss unless Bell Diner had bought insurance on the flour before the shipment left."],"a":1,"cite":"UCC §2-509(1)(a)","rat":"In a shipment contract that does not require delivery at a particular destination, risk of loss passes to the buyer when the goods are duly delivered to the carrier.","ex":["In a shipment contract that does not require delivery at a particular destination, risk of loss passes to the buyer when the goods are duly delivered to the carrier.","The receipt rule applies when the contract does not involve carrier shipment. Here the carrier rule applies.","The rule places risk of loss on one party. It does not split the loss when neither party is at fault.","Risk of loss does not depend on whether the buyer bought insurance."],"wt":["","concept","concept","concept"],"tags":{"area":"II","group":"B","skill":"Application","diff":1},"asof":"2026-09-29","rl":"In a shipment contract, risk of loss passes to the buyer when goods are delivered to the carrier."}},{"i":"REG-II-B-0024","t":"Sierra Grains signed three contracts, each to deliver 400 tons of feed grain to a different customer, for a total of 1,200 tons. The contracts said nothing about crop failure. A severe drought that no one could have foreseen limited Sierra's supply to 900 tons for the season. Sierra promptly told all three customers of the shortage and of the estimated quantity it would allocate to each, and it divided the 900 tons among them in proportion to their orders. One customer sued for the full 400 tons. Which statement is most accurate?","mc":{"s":"Sierra Grains signed three contracts, each to deliver 400 tons of feed grain to a different customer, for a total of 1,200 tons. The contracts said nothing about crop failure. A severe drought that no one could have foreseen limited Sierra's supply to 900 tons for the season. Sierra promptly told all three customers of the shortage and of the estimated quantity it would allocate to each, and it divided the 900 tons among them in proportion to their orders. One customer sued for the full 400 tons. Which statement is most accurate?","d":"","o":["Sierra is excused from all deliveries, because a drought is an act of nature that ends every contract dependent on the crop.","Sierra is liable for the full 400 tons to each customer and must buy the difference on the open market at any price.","Sierra is excused from full delivery, because the drought made performance impracticable and Sierra allocated its supply fairly and gave prompt notice.","Sierra is excused only if it filled the contracts in the order signed until the 900 tons ran out, leaving the last customer with nothing."],"a":3,"cite":"UCC §2-615(a), (b), (c)","rat":"A seller is excused when performance is made impracticable by a contingency whose non-occurrence was a basic assumption of the contract, if it allocates its limited supply fairly and reasonably and seasonably notifies buyers.","ex":["The excuse is partial when only part of the capacity is affected. The seller must still allocate what it has.","Impracticability caused by an unforeseen contingency excuses full performance if the seller allocates fairly and gives notice.","A seller is excused when performance is made impracticable by a contingency whose non-occurrence was a basic assumption of the contract, if it allocates its limited supply fairly and reasonably and seasonably notifies buyers.","The statute allows any fair and reasonable method of allocation. It does not require filling contracts in the order signed."],"wt":["concept","concept","","concept"],"tags":{"area":"II","group":"B","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Impracticability from an unforeseen contingency excuses a seller who fairly allocates production among customers and gives notice."}}],"5":[{"i":"REG-II-B-0005","t":"Halo Co. contracted to buy 5,000 pounds of resin from Kemp at $3.00 per pound. Kemp failed to deliver. Halo promptly and in good faith bought 5,000 pounds elsewhere at $3.40 per pound and paid $150 in incidental costs. Halo saved no expenses. What may Halo recover from Kemp?","mc":{"s":"Halo Co. contracted to buy 5,000 pounds of resin from Kemp at $3.00 per pound. Kemp failed to deliver. Halo promptly and in good faith bought 5,000 pounds elsewhere at $3.40 per pound and paid $150 in incidental costs. Halo saved no expenses. What may Halo recover from Kemp?","d":"","o":["$2,000","$2,150","$17,000","$17,150"],"a":2,"cite":"UCC §2-712(2); UCC §2-715","rat":"Cover damages are cost of cover minus contract price: 5,000 x ($3.40 - $3.00) = $2,000, plus incidental damages of $150.","ex":["This is the cover price difference alone. It leaves out the $150 of incidental damages, which are recoverable in addition.","Cover damages are cost of cover minus contract price: 5,000 x ($3.40 - $3.00) = $2,000, plus incidental damages of $150.","This is the full cost of the substitute resin (5,000 x $3.40). Halo would have paid $15,000 anyway, so only the excess is damages.","This adds the incidental costs to the full cost of the substitute resin. It repeats the error of ignoring the $15,000 contract price."],"wt":["calc","","calc","calc"],"tags":{"area":"II","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Cover damages equal the cover price minus the contract price, plus incidental damages.","calc":1,"steps":["Cover price difference per pound: $3.40 - $3.00 = $0.40","Cover damages: 5,000 x $0.40 = $2,000","Add incidental damages: $2,000 + $150 = $2,150"]}},{"i":"REG-II-B-0007","t":"Jonas bought a machine under a written sales contract that had no term on time limits. The seller delivered a defective machine on March 1, 2021. Jonas did not discover the defect until 2025 and sued for breach on March 15, 2026. Which statement is most accurate?","mc":{"s":"Jonas bought a machine under a written sales contract that had no term on time limits. The seller delivered a defective machine on March 1, 2021. Jonas did not discover the defect until 2025 and sued for breach on March 15, 2026. Which statement is most accurate?","d":"","o":["The suit is timely, because the limitation period for a written sales contract is six years from delivery.","The suit is timely, because the period starts only when the buyer discovers the defect in the machine.","The suit is likely untimely, because the four-year period generally runs from delivery, not from discovery.","The suit is timely, because a contract that sets no time limit is subject to no limitation period."],"a":3,"cite":"UCC §2-725(1), (2)","rat":"The Article 2 period is four years from when the cause of action accrues, and accrual generally does not wait for discovery.","ex":["The Article 2 period is four years. Six years is a common general contract period under other law.","Discovery rules are limited to special cases such as warranties that extend to future performance.","The Article 2 period is four years from when the cause of action accrues, and accrual generally does not wait for discovery.","Article 2 sets a limitation period for sales contract claims even when the contract is silent."],"wt":["limit","concept","","concept"],"tags":{"area":"II","group":"B","skill":"Application","diff":3},"asof":"2026-09-29","rl":"The UCC limitation period for sales contract claims is four years from tender of delivery, regardless of discovery."}},{"i":"REG-II-B-0013","t":"Wren Hardware, a merchant that sells power tools, sold Pavel a table saw. The written sales contract contained, in the same size and style of type as the rest of the contract, the sentence \"Seller makes no warranties.\" On first use the blade guard failed, and the saw was not fit for the ordinary purposes of a table saw. Which statement is most accurate?","mc":{"s":"Wren Hardware, a merchant that sells power tools, sold Pavel a table saw. The written sales contract contained, in the same size and style of type as the rest of the contract, the sentence \"Seller makes no warranties.\" On first use the blade guard failed, and the saw was not fit for the ordinary purposes of a table saw. Which statement is most accurate?","d":"","o":["Wren Hardware is not liable, because a general statement that it makes no warranties excludes every implied warranty.","Wren Hardware likely breached the implied warranty of merchantability, because an effective disclaimer must mention merchantability and be conspicuous.","Wren Hardware is not liable, because implied warranties arise only when the seller gives a written promise about the goods being sold.","Wren Hardware is liable only if Pavel proves that Wren Hardware knew of the defect when it sold the saw."],"a":2,"cite":"UCC §2-314(1), (2); UCC §2-316(2)","rat":"The implied warranty of merchantability arises when a merchant sells goods of that kind.","ex":["A general statement does not exclude the implied warranty of merchantability and was not conspicuous either.","The implied warranty of merchantability arises when a merchant sells goods of that kind. To exclude it, the language must mention merchantability and, in a writing, be conspicuous.","Implied warranties arise by operation of law and need no written promise.","The seller's knowledge of the defect is not an element of the implied warranty of merchantability."],"wt":["concept","","concept","concept"],"tags":{"area":"II","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A merchant's disclaimer of the implied warranty of merchantability must mention merchantability and be conspicuous."}},{"i":"REG-II-B-0014","t":"Lund Co. agreed to sell Mesa Inc. 4,000 units of a standard component for $12.50 per unit, with tender on June 30. On June 1, Mesa Inc. wrongfully repudiated the contract, and Lund Co. did not resell the units. The market price at the time and place for tender was $10.00 per unit. Lund Co. had no incidental damages and saved no expenses, and the market-price measure is adequate to put Lund Co. in as good a position as performance would have. What are Lund Co.'s damages?","mc":{"s":"Lund Co. agreed to sell Mesa Inc. 4,000 units of a standard component for $12.50 per unit, with tender on June 30. On June 1, Mesa Inc. wrongfully repudiated the contract, and Lund Co. did not resell the units. The market price at the time and place for tender was $10.00 per unit. Lund Co. had no incidental damages and saved no expenses, and the market-price measure is adequate to put Lund Co. in as good a position as performance would have. What are Lund Co.'s damages?","d":"","o":["$2,500","$10,000","$40,000","$50,000"],"a":2,"cite":"UCC §2-708(1)","rat":"Damages are the unpaid contract price less the market price: ($12.50 - $10.00) x 4,000 units = $10,000.","ex":["This is the per-unit difference of $2.50 and does not multiply by the 4,000 units.","Damages are the unpaid contract price less the market price: ($12.50 - $10.00) x 4,000 units = $10,000.","This is the market value of the units (4,000 x $10.00), not the seller's loss.","This is the full contract price (4,000 x $12.50). The seller does not recover the price where it still holds the goods and market damages are adequate."],"wt":["calc","","calc","concept"],"tags":{"area":"II","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A seller's market-price damages equal contract price minus market price times the units, plus incidentals.","calc":1,"steps":["Per-unit shortfall: $12.50 - $10.00 = $2.50","Total: $2.50 x 4,000 = $10,000"]}},{"i":"REG-II-B-0017","t":"Ferro Corp. sold Halden Bakery an industrial oven under a written contract that limited Halden's remedy to repair or replacement of defective parts and said this remedy was exclusive. The oven's controller failed repeatedly, and Ferro's repair attempts over six months did not fix it. Which statement is most accurate about Halden Bakery's remedies?","mc":{"s":"Ferro Corp. sold Halden Bakery an industrial oven under a written contract that limited Halden's remedy to repair or replacement of defective parts and said this remedy was exclusive. The oven's controller failed repeatedly, and Ferro's repair attempts over six months did not fix it. Which statement is most accurate about Halden Bakery's remedies?","d":"","o":["Halden is limited to repair or replacement, because an agreed exclusive remedy is binding whatever happens.","Halden automatically recovers lost profits, because a failed remedy also cancels any clause excluding consequential damages in the same contract.","Halden may recover only a refund of the price, because a buyer's remedy after failed repairs is limited to that refund.","Halden is no longer limited to repair or replacement, because the exclusive remedy failed of its essential purpose."],"a":4,"cite":"UCC §2-719(1), (2), (3)","rat":"Where circumstances cause an exclusive or limited remedy to fail of its essential purpose, remedy may be had as provided in the Uniform Commercial Code.","ex":["The Code lets a party escape an exclusive remedy that fails of its essential purpose.","A consequential damages exclusion is judged separately and stands unless it is unconscionable.","The Code does not cap the buyer at a refund. It opens the general remedies of the Article.","Where circumstances cause an exclusive or limited remedy to fail of its essential purpose, remedy may be had as provided in the Uniform Commercial Code."],"wt":["concept","concept","concept",""],"tags":{"area":"II","group":"B","skill":"Application","diff":3},"asof":"2026-09-29","rl":"An exclusive remedy that fails of its essential purpose opens the general UCC remedies, but a consequential damages exclusion is judged separately."}},{"i":"REG-II-B-0018","t":"Nora left her antique watch with Grady Jewelers, a shop that both sells and repairs watches, for cleaning. Grady mistakenly placed it in the display case and sold it for $3,000 to Lila, a customer who paid cash and knew nothing about Nora. Nora demanded the watch from Lila. Which statement is most accurate?","mc":{"s":"Nora left her antique watch with Grady Jewelers, a shop that both sells and repairs watches, for cleaning. Grady mistakenly placed it in the display case and sold it for $3,000 to Lila, a customer who paid cash and knew nothing about Nora. Nora demanded the watch from Lila. Which statement is most accurate?","d":"","o":["Nora may recover the watch, because a seller cannot transfer better title than the seller had, and Grady did not own the watch.","Nora may recover the watch, because leaving it for repair, rather than for sale, is not an entrustment.","Lila keeps the watch only if she proves that Nora authorized Grady in writing to sell it.","Lila keeps the watch, because Nora entrusted it to a merchant who deals in such goods and it could pass her rights to a buyer in ordinary course."],"a":4,"cite":"UCC §2-403(2), (3)","rat":"Entrusting goods to a merchant who deals in goods of that kind gives the merchant power to transfer the entruster's rights to a buyer in ordinary course of business, and entrusting includes any delivery.","ex":["That general rule is displaced by the entrustment rule for a buyer in ordinary course.","Entrusting includes any delivery, and it applies regardless of the purpose of the delivery.","Authority to sell is not required. The entrustment rule supplies the power to transfer.","Entrusting goods to a merchant who deals in goods of that kind gives the merchant power to transfer the entruster's rights to a buyer in ordinary course of business, and entrusting includes any delivery."],"wt":["concept","concept","concept",""],"tags":{"area":"II","group":"B","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A buyer in ordinary course from a merchant entrusted with goods takes good title against the owner."}},{"i":"REG-II-B-0020","t":"Vale Furniture agreed to sell 60 identical office chairs to Trent at $85 each. Trent wrongfully refused to take the chairs. After reasonable notice to Trent, Vale sold the chairs at a public sale in good faith and in a commercially reasonable manner for $70 each. Vale spent $150 on incidental expenses of the resale and saved no other expenses. What is Vale's damages under the resale remedy?","mc":{"s":"Vale Furniture agreed to sell 60 identical office chairs to Trent at $85 each. Trent wrongfully refused to take the chairs. After reasonable notice to Trent, Vale sold the chairs at a public sale in good faith and in a commercially reasonable manner for $70 each. Vale spent $150 on incidental expenses of the resale and saved no other expenses. What is Vale's damages under the resale remedy?","d":"","o":["$750","$900","$1,050","$4,350"],"a":3,"cite":"UCC §2-706(1); UCC §2-710","rat":"The difference between the contract price and the resale price is $15 per chair, or $900 on 60 chairs, plus $150 of incidental damages, for $1,050.","ex":["This subtracts the incidental expenses ($900 less $150) instead of adding them.","This is the price difference alone and leaves out the incidental damages.","The difference between the contract price and the resale price is $15 per chair, or $900 on 60 chairs, plus $150 of incidental damages, for $1,050.","This adds the incidental expenses to the resale proceeds ($4,200 plus $150), which is not the measure of the seller's damages."],"wt":["calc","calc","","calc"],"tags":{"area":"II","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A seller's resale damages equal contract price minus resale price plus incidental damages.","calc":1,"steps":["Contract price 60 x $85 = $5,100","Resale price 60 x $70 = $4,200","Difference $5,100 - $4,200 = $900","Add incidental damages $150 = $1,050"]}},{"i":"REG-II-B-0021","t":"Rosa Fabrication contracted to build a conveyor cut to the exact dimensions of Kade Co.'s plant and to sell it for $46,000. Before delivery, Kade repudiated the contract. Rosa completed the conveyor. After a reasonable effort, Rosa could not resell it at any reasonable price because no other buyer had a plant of that size. Which statement is most accurate about Rosa's remedy?","mc":{"s":"Rosa Fabrication contracted to build a conveyor cut to the exact dimensions of Kade Co.'s plant and to sell it for $46,000. Before delivery, Kade repudiated the contract. Rosa completed the conveyor. After a reasonable effort, Rosa could not resell it at any reasonable price because no other buyer had a plant of that size. Which statement is most accurate about Rosa's remedy?","d":"","o":["Rosa may recover only the difference between the contract price and the market price, because a seller may not sue for the price of goods the buyer has not accepted.","Rosa may recover only the costs she incurred in reliance on the contract, because a custom item is not covered by the sales remedies.","Rosa may recover the full $46,000 price, because the goods are identified to the contract and cannot be resold at a reasonable price, and she must hold them for Kade.","Rosa may recover the price and keep the conveyor for her own use or resale without any credit to Kade for later proceeds."],"a":3,"cite":"UCC §2-709(1)(b), (2)","rat":"A seller may recover the price of identified goods that it is unable, after reasonable effort, to resell at a reasonable price.","ex":["Recovery of the price is allowed for identified goods that cannot be resold at a reasonable price, even though the buyer did not accept them.","Custom-made goods are still goods under the sales article, and the seller's remedies include an action for the price in this situation.","A seller may recover the price of identified goods that it is unable, after reasonable effort, to resell at a reasonable price. The seller must hold the goods for the buyer and credit the buyer with the proceeds of any later resale.","The seller must hold the identified goods for the buyer, and any resale proceeds before payment of the judgment are credited to the buyer."],"wt":["concept","concept","","concept"],"tags":{"area":"II","group":"B","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A seller may recover the price of identified goods that cannot reasonably be resold after the buyer repudiates."}},{"i":"REG-II-B-0022","t":"Ledger Foods contracted to buy a specialty oven from Hart Equipment for $2,400 and paid a $1,000 deposit. The contract had no term that liquidated damages. Ledger later wrongfully canceled, and Hart kept the oven. Hart proved no actual damages. How much of the deposit is Ledger entitled to recover in restitution?","mc":{"s":"Ledger Foods contracted to buy a specialty oven from Hart Equipment for $2,400 and paid a $1,000 deposit. The contract had no term that liquidated damages. Ledger later wrongfully canceled, and Hart kept the oven. Hart proved no actual damages. How much of the deposit is Ledger entitled to recover in restitution?","d":"","o":["$480","$500","$520","$1,000"],"a":3,"cite":"UCC §2-718(2)(b), (3)","rat":"Absent a liquidated damages term, the seller may keep the smaller of 20 percent of the total price ($480) or $500.","ex":["This is the amount the seller may keep, not the amount the buyer recovers.","This uses the flat $500 as the amount to keep. The seller keeps the smaller of $480 and $500, so only $480 is kept and the refund is larger.","Absent a liquidated damages term, the seller may keep the smaller of 20 percent of the total price ($480) or $500. Ledger recovers $1,000 less $480, or $520.","This refunds the whole deposit and ignores the seller's statutory right to keep the smaller of 20 percent of the price or $500."],"wt":["calc","limit","","concept"],"tags":{"area":"II","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A defaulting buyer recovers the deposit less the seller's right to keep the smaller of 20% of price or $500.","calc":1,"steps":["20% of total price 0.20 x $2,400 = $480","Smaller of $480 and $500 = $480","Restitution $1,000 - $480 = $520"]}},{"i":"REG-II-B-0023","t":"Winn Cafe bought a commercial refrigerator. The first time it was turned on, its compressor failed on and off, but Winn Cafe kept the unit after the seller promised to fix it. The seller made three repair visits over five weeks, but the problem continued. The day after the last failed repair, Winn Cafe told the seller in writing that it revoked its acceptance because the defect substantially impaired the refrigerator's value. The seller argued that Winn Cafe had accepted the goods and used them, so acceptance was final. Which statement is most accurate?","mc":{"s":"Winn Cafe bought a commercial refrigerator. The first time it was turned on, its compressor failed on and off, but Winn Cafe kept the unit after the seller promised to fix it. The seller made three repair visits over five weeks, but the problem continued. The day after the last failed repair, Winn Cafe told the seller in writing that it revoked its acceptance because the defect substantially impaired the refrigerator's value. The seller argued that Winn Cafe had accepted the goods and used them, so acceptance was final. Which statement is most accurate?","d":"","o":["The revocation is not effective, because once a buyer has used the goods for several weeks, acceptance is final and only damages remain.","The revocation is effective only if Winn Cafe first shipped the refrigerator back to the seller at the seller's cost.","The revocation is effective, because Winn Cafe accepted assuming the defect would be cured, it was not, and revocation came within a reasonable time.","The revocation is effective only if the defect was one Winn Cafe could not have discovered before it accepted the refrigerator."],"a":3,"cite":"UCC §2-608(1)(a), (2)","rat":"A buyer may revoke acceptance of goods whose nonconformity substantially impairs their value if the buyer accepted on the reasonable assumption that it would be cured and it was not seasonably cured.","ex":["Use of the goods does not make acceptance final when the requirements for revocation are met.","Revocation takes effect when the buyer notifies the seller. Returning the goods is not a condition.","A buyer may revoke acceptance of goods whose nonconformity substantially impairs their value if the buyer accepted on the reasonable assumption that it would be cured and it was not seasonably cured. The revocation must occur within a reasonable time and before substantial change not caused by the defect.","Difficulty of discovery is a separate ground. Acceptance made on the assumption of cure is an independent ground for revocation."],"wt":["concept","concept","","concept"],"tags":{"area":"II","group":"B","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A buyer may revoke acceptance if the defect substantially impairs value and acceptance was reasonably induced by assurance of cure."}}],"6":[{"i":"REG-II-C-0001","t":"On May 1, Ana borrowed $10,000 from Bank and orally agreed that Bank would have a security interest in Ana's delivery van, which she owns. Ana signed nothing, and Bank never took possession of the van. Bank did lend the $10,000. Which statement is most accurate?","mc":{"s":"On May 1, Ana borrowed $10,000 from Bank and orally agreed that Bank would have a security interest in Ana's delivery van, which she owns. Ana signed nothing, and Bank never took possession of the van. Bank did lend the $10,000. Which statement is most accurate?","d":"","o":["The security interest is enforceable against Ana, because Bank gave value and Ana owns the van used as collateral.","The security interest is not enforceable against Ana, because there is no signed agreement describing the van and Bank lacks possession.","The security interest is enforceable against Ana, because her oral agreement is enough once Bank has given value, even without possession.","The security interest is not enforceable against Ana, because value is given only when the loan is repaid in full, and Ana has not repaid."],"a":2,"cite":"UCC §9-203(b)","rat":"Attachment needs value, rights in the collateral, and either an authenticated agreement describing the collateral or possession under the agreement.","ex":["Value and rights in the collateral are necessary but not sufficient.","Attachment needs value, rights in the collateral, and either an authenticated agreement describing the collateral or possession under the agreement. The third element is missing.","An oral agreement works only if the secured party has possession under it.","Value is given when the loan is made. Repayment is not required."],"wt":["concept","","concept","concept"],"tags":{"area":"II","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A security interest attaches only with value, rights in the collateral, and a signed security agreement or possession."}},{"i":"REG-II-C-0002","t":"Ravi signed a security agreement giving Lender a security interest in his inventory, and Lender gave $60,000 in value. Lender never filed a financing statement and does not possess or control the inventory. Which statement is most accurate?","mc":{"s":"Ravi signed a security agreement giving Lender a security interest in his inventory, and Lender gave $60,000 in value. Lender never filed a financing statement and does not possess or control the inventory. Which statement is most accurate?","d":"","o":["The security interest is perfected, because Ravi's signing of the agreement completes both attachment and perfection.","The security interest is perfected automatically 20 days after Ravi signs, even without a filing or possession.","The security interest has attached but is not perfected, because Lender has not filed and has no possession or control.","The security interest has not attached, because a security interest attaches only at the moment it is perfected by a filing."],"a":3,"cite":"UCC §9-308(a); UCC §9-310(a)","rat":"Attachment is complete, but perfection generally requires filing or another perfection step, and none has occurred.","ex":["Signing supports attachment only.","There is no general 20-day automatic perfection. Twenty days matters only for certain purchase-money priority.","Attachment is complete, but perfection generally requires filing or another perfection step, and none has occurred.","Attachment and perfection are separate. The interest attached when the elements were met."],"wt":["concept","limit","","concept"],"tags":{"area":"II","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"An attached security interest is perfected only by filing, possession or control, not by attachment alone."}},{"i":"REG-II-C-0003","t":"Sunil pawned his guitar to a pawn shop for $500 and handed it over. The shop holds the guitar and filed no financing statement. Which statement is most accurate about perfection?","mc":{"s":"Sunil pawned his guitar to a pawn shop for $500 and handed it over. The shop holds the guitar and filed no financing statement. Which statement is most accurate about perfection?","d":"","o":["The pawn shop's security interest is perfected, because the shop took possession of the guitar.","The security interest is not perfected, because filing a financing statement is the only way to perfect in goods.","The security interest is not perfected, because perfection by possession is limited to inventory held for sale.","The security interest is perfected only if Sunil also signs a financing statement that the shop then files."],"a":1,"cite":"UCC §9-313(a)","rat":"A secured party may perfect a security interest in goods by taking possession of the collateral.","ex":["A secured party may perfect a security interest in goods by taking possession of the collateral.","Possession is an alternative to filing for goods.","Possession can perfect for goods generally, not only inventory.","A financing statement is not needed when perfection is by possession."],"wt":["","concept","concept","concept"],"tags":{"area":"II","group":"C","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A secured party perfects a security interest in goods by taking possession, without filing."}},{"i":"REG-II-C-0004","t":"Bank X lent Dee $50,000 on March 1 and filed a financing statement covering Dee's equipment on March 2. Bank Y lent Dee $30,000 on March 5 against the same equipment and filed on March 8. Both security interests attached and were perfected by filing, and neither is a purchase-money interest. Which bank has priority in the equipment?","mc":{"s":"Bank X lent Dee $50,000 on March 1 and filed a financing statement covering Dee's equipment on March 2. Bank Y lent Dee $30,000 on March 5 against the same equipment and filed on March 8. Both security interests attached and were perfected by filing, and neither is a purchase-money interest. Which bank has priority in the equipment?","d":"","o":["Bank Y has priority, because it took its security interest after Bank X and the later lender wins.","Bank Y has priority, because its more recent loan reflects Dee's current financial position.","Bank X has priority, because it was the first to file its financing statement.","Bank X and Bank Y share equally in the equipment, because both perfected by filing."],"a":3,"cite":"UCC §9-322(a)(1)","rat":"Conflicting perfected security interests rank by priority in time of filing or perfection, and X filed first.","ex":["There is no rule preferring the later lender.","Knowledge and recency do not set priority.","Conflicting perfected security interests rank by priority in time of filing or perfection, and X filed first.","Perfected interests are ranked by time, not shared, unless the parties agree otherwise."],"wt":["concept","concept","","concept"],"tags":{"area":"II","group":"C","skill":"Application","diff":1},"asof":"2026-09-29","rl":"Among perfected security interests in the same collateral, the first to file or perfect has priority."}},{"i":"REG-II-C-0005","t":"First Bank holds a perfected security interest, filed three years ago, in all equipment Vela Co. owns now or acquires later. On September 1, Vela received a new lathe from Toolco on credit, and Toolco kept a purchase-money security interest in it. Toolco filed a financing statement on September 18. Which statement is most accurate about priority in the lathe?","mc":{"s":"First Bank holds a perfected security interest, filed three years ago, in all equipment Vela Co. owns now or acquires later. On September 1, Vela received a new lathe from Toolco on credit, and Toolco kept a purchase-money security interest in it. Toolco filed a financing statement on September 18. Which statement is most accurate about priority in the lathe?","d":"","o":["First Bank has priority, because it filed first and an earlier filer wins in every purchase-money priority contest.","Toolco likely has priority, because its purchase-money interest was perfected within 20 days after Vela received the lathe.","Toolco has priority only if First Bank consents in writing to the purchase-money interest.","Toolco has no priority, because it filed its financing statement after Vela had already taken possession of the lathe."],"a":2,"cite":"UCC §9-324(a)","rat":"September 18 is within 20 days after September 1, so Toolco's purchase-money interest beats First Bank's earlier filing.","ex":["The purchase-money rule gives a timely perfected interest priority over an earlier filer.","September 18 is within 20 days after September 1, so Toolco's purchase-money interest beats First Bank's earlier filing.","Consent is not required for this rule.","Filing within 20 days after possession is enough."],"wt":["concept","","concept","limit"],"tags":{"area":"II","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A purchase-money security interest perfected within 20 days after the debtor receives possession beats an earlier filer."}},{"i":"REG-II-C-0006","t":"Dora defaulted on her car loan. At 3 a.m., Lender's agent cut the lock on Dora's closed garage over her shouted objection and drove the car away without a court order. Which statement is most accurate?","mc":{"s":"Dora defaulted on her car loan. At 3 a.m., Lender's agent cut the lock on Dora's closed garage over her shouted objection and drove the car away without a court order. Which statement is most accurate?","d":"","o":["The repossession is proper, because a default lets the lender repossess by any means available to it, day or night.","The repossession is likely improper, because self-help is allowed only when it proceeds without a breach of the peace.","The repossession is proper, because Dora agreed to loan terms that allow repossession after default.","The repossession is proper, because Lender can cure the breach of the peace by sending notice after taking the car."],"a":2,"cite":"UCC §9-609(a), (b)","rat":"After default a secured party may repossess without judicial process only if it proceeds without breach of the peace, and breaking in over an objection does not qualify.","ex":["Self-help is limited by the no-breach-of-the-peace condition.","After default a secured party may repossess without judicial process only if it proceeds without breach of the peace, and breaking in over an objection does not qualify.","Agreement to a loan does not authorize a breach of the peace.","Later notice does not cure a breach of the peace."],"wt":["concept","","concept","concept"],"tags":{"area":"II","group":"C","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Self-help repossession is allowed only without breach of the peace."}},{"i":"REG-II-C-0008","t":"Brill Bank has a perfected security interest, by filing, in all inventory of Cobb Motors, a car dealer. Cobb Motors sold a car from inventory and received a $2,000 cash down payment and the buyer's $18,000 promissory note. Twenty-five days after the sale, Cobb Motors still holds the note and the cash. Brill Bank filed nothing further. Which statement is most accurate about Brill Bank's interest in the note?","mc":{"s":"Brill Bank has a perfected security interest, by filing, in all inventory of Cobb Motors, a car dealer. Cobb Motors sold a car from inventory and received a $2,000 cash down payment and the buyer's $18,000 promissory note. Twenty-five days after the sale, Cobb Motors still holds the note and the cash. Brill Bank filed nothing further. Which statement is most accurate about Brill Bank's interest in the note?","d":"","o":["The interest in the note became unperfected on the 21st day, because perfection in proceeds ends then in every case.","The interest in the note is still perfected, because the filed statement covers the inventory and a note can be perfected by filing in the same office.","Brill Bank has no interest in the note, because the buyer took the car free and that also ended the bank's rights against Cobb Motors.","Brill Bank's interest covers only the $2,000 in cash, because a security interest in proceeds is limited to money."],"a":2,"cite":"UCC §9-315(a), (c), (d)","rat":"A security interest attaches to identifiable proceeds and is perfected if the interest in the original collateral was.","ex":["The 21st-day cutoff has exceptions, including the one that applies to a note perfectible by filing in the same office.","A security interest attaches to identifiable proceeds and is perfected if the interest in the original collateral was. It stays perfected beyond 20 days where the filed statement covers the original collateral, the proceeds can be perfected by filing there, and they were not acquired with cash proceeds.","A buyer in ordinary course may take the car free, but the bank's interest attaches to identifiable proceeds.","Proceeds include what is received on the disposition, such as a promissory note, not only cash."],"wt":["concept","","concept","concept"],"tags":{"area":"II","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A perfected security interest continues in identifiable proceeds, including a note received on sale of inventory."}},{"i":"REG-II-C-0009","t":"On May 1, Weld Bank signed a security agreement with Tuck Fabrication covering its equipment and lent it $90,000. Weld Bank neither filed a financing statement nor took possession. On May 20, Rye, a judgment creditor of Tuck, obtained a judicial lien on the equipment. On June 5, Weld Bank filed a financing statement. The loan was not a purchase-money loan. Who has priority in the equipment?","mc":{"s":"On May 1, Weld Bank signed a security agreement with Tuck Fabrication covering its equipment and lent it $90,000. Weld Bank neither filed a financing statement nor took possession. On May 20, Rye, a judgment creditor of Tuck, obtained a judicial lien on the equipment. On June 5, Weld Bank filed a financing statement. The loan was not a purchase-money loan. Who has priority in the equipment?","d":"","o":["Weld Bank, because its security interest attached on May 1, before Rye's lien arose.","Weld Bank, because a financing statement filed on any later date relates back to the date of the security agreement.","Neither of them, because a lien creditor and an unperfected secured party share the equipment equally.","Rye, because Weld Bank's security interest was still unperfected when Rye became a lien creditor."],"a":4,"cite":"UCC §9-317(a)(2)","rat":"A security interest is subordinate to a person who becomes a lien creditor before the interest is perfected or, when attachment conditions are met, before a financing statement is filed.","ex":["Attachment alone does not beat a lien creditor. Perfection, or a filing after attachment, is needed first.","A financing statement does not relate back. Priority against the lien creditor is fixed by what happened before May 20.","The Code does not split value between them. It ranks the lien creditor first.","A security interest is subordinate to a person who becomes a lien creditor before the interest is perfected or, when attachment conditions are met, before a financing statement is filed. Weld Bank did neither before May 20."],"wt":["concept","concept","concept",""],"tags":{"area":"II","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A lien creditor beats a security interest that was unperfected when the lien arose."}},{"i":"REG-II-C-0010","t":"Kestrel Bank holds a perfected security interest in all inventory of Lumen Boats, a boat dealer. The loan documents did not permit sales free of the interest. Ben, who knew that Kestrel Bank had a security interest in Lumen's inventory, bought a boat from Lumen's showroom in the ordinary course of business for $25,000 cash. Lumen later defaulted on its loan, and Kestrel Bank wants to repossess the boat from Ben. Which statement is most accurate?","mc":{"s":"Kestrel Bank holds a perfected security interest in all inventory of Lumen Boats, a boat dealer. The loan documents did not permit sales free of the interest. Ben, who knew that Kestrel Bank had a security interest in Lumen's inventory, bought a boat from Lumen's showroom in the ordinary course of business for $25,000 cash. Lumen later defaulted on its loan, and Kestrel Bank wants to repossess the boat from Ben. Which statement is most accurate?","d":"","o":["Ben takes the boat free of the security interest, because a buyer in ordinary course takes free even if the interest is perfected and known to him.","Kestrel Bank may repossess the boat, because a perfected security interest binds every buyer who knew about it when buying the boat.","Kestrel Bank may repossess the boat, because the loan documents barred sales of inventory free of the security interest.","Ben takes the boat free only if he paid the price directly to Kestrel Bank or to a bank account that Kestrel Bank controls."],"a":1,"cite":"UCC §9-320(a)","rat":"A buyer in ordinary course of business takes free of a security interest created by the buyer's seller, even if the interest is perfected and the buyer knows of its existence.","ex":["A buyer in ordinary course of business takes free of a security interest created by the buyer's seller, even if the interest is perfected and the buyer knows of its existence.","The rule protecting a buyer in ordinary course expressly applies even where the buyer knows of the interest.","The buyer's protection does not depend on the secured party's authorization. Kestrel's remedy is against Lumen and the proceeds.","Payment to the secured party is not required for a buyer in ordinary course."],"wt":["","concept","concept","concept"],"tags":{"area":"II","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A buyer in ordinary course takes free of the seller's inventory security interest even if he knows of it."}},{"i":"REG-II-C-0011","t":"After Drew defaulted on a $60,000 loan, Fin Bank, which held a perfected security interest in Drew's delivery truck, took the truck and sold it at a commercially reasonable public sale for $38,000 cash. Fin Bank incurred $3,000 of reasonable expenses in retaking and selling the truck. No subordinate lienholder made a demand for proceeds. What deficiency does Drew owe Fin Bank?","mc":{"s":"After Drew defaulted on a $60,000 loan, Fin Bank, which held a perfected security interest in Drew's delivery truck, took the truck and sold it at a commercially reasonable public sale for $38,000 cash. Fin Bank incurred $3,000 of reasonable expenses in retaking and selling the truck. No subordinate lienholder made a demand for proceeds. What deficiency does Drew owe Fin Bank?","d":"","o":["$19,000","$22,000","$25,000","$60,000"],"a":3,"cite":"UCC §9-615(a), (d)","rat":"Cash proceeds first cover reasonable expenses ($3,000), then the debt: $38,000 - $3,000 = $35,000 applied, so the deficiency is $60,000 - $35,000 = $25,000.","ex":["This adds the $3,000 of expenses to the sale proceeds instead of taking them out first.","This applies the whole $38,000 to the debt and ignores the reasonable expenses that come first.","Cash proceeds first cover reasonable expenses ($3,000), then the debt: $38,000 - $3,000 = $35,000 applied, so the deficiency is $60,000 - $35,000 = $25,000.","This ignores the sale proceeds. The obligor is liable only for the deficiency after proceeds are applied."],"wt":["calc","calc","","concept"],"tags":{"area":"II","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Sale proceeds first pay repossession and sale expenses, then the debt, and the debtor owes any deficiency.","calc":1,"steps":["Net proceeds after expenses: $38,000 - $3,000 = $35,000","Deficiency: $60,000 - $35,000 = $25,000"]}},{"i":"REG-II-C-0012","t":"Petra defaulted on a car loan from Star Finance, which repossessed her car and sent notice that it would sell the car at a public sale on June 20. On June 15, Petra offered to pay the entire loan balance plus Star Finance's reasonable repossession expenses. Star Finance had not yet sold the car or signed a contract to sell it. Which statement is most accurate?","mc":{"s":"Petra defaulted on a car loan from Star Finance, which repossessed her car and sent notice that it would sell the car at a public sale on June 20. On June 15, Petra offered to pay the entire loan balance plus Star Finance's reasonable repossession expenses. Star Finance had not yet sold the car or signed a contract to sell it. Which statement is most accurate?","d":"","o":["Petra may not redeem, because after default the debtor's only right is to receive any surplus from a sale.","Petra may redeem by paying only the missed installments and late fees, because a default cure is all that redemption requires after repossession.","Petra may redeem only after the sale, by reimbursing the buyer for the price the buyer paid.","Petra may redeem the car, because redemption is allowed before disposition if she tenders all secured obligations and the reasonable expenses."],"a":4,"cite":"UCC §9-623(a), (b), (c)","rat":"A debtor may redeem collateral at any time before the secured party has collected it, disposed of it or contracted to dispose of it, or accepted it in satisfaction, by tendering all secured obligations and expenses.","ex":["The debtor keeps a right to redeem before disposition. A surplus right comes later.","Redemption requires tender of all obligations secured by the collateral, not only the past-due amounts.","The right to redeem ends once the collateral is disposed of or a contract for disposition is made.","A debtor may redeem collateral at any time before the secured party has collected it, disposed of it or contracted to dispose of it, or accepted it in satisfaction, by tendering all secured obligations and expenses."],"wt":["concept","concept","concept",""],"tags":{"area":"II","group":"C","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A debtor may redeem collateral before disposition by tendering all secured obligations plus expenses."}},{"i":"REG-II-C-0013","t":"On March 1 of Year 1, Nash Bank filed a financing statement covering Orla Co.'s equipment and perfected its security interest by that filing alone. On August 1 of Year 5, about seven months before the five-year period ended, Nash Bank filed a continuation statement. Nothing else was filed. On April 1 of Year 6, Orla Co. sold the equipment for value to Pike. Which statement is most accurate about Nash Bank's position as against Pike?","mc":{"s":"On March 1 of Year 1, Nash Bank filed a financing statement covering Orla Co.'s equipment and perfected its security interest by that filing alone. On August 1 of Year 5, about seven months before the five-year period ended, Nash Bank filed a continuation statement. Nothing else was filed. On April 1 of Year 6, Orla Co. sold the equipment for value to Pike. Which statement is most accurate about Nash Bank's position as against Pike?","d":"","o":["Nash Bank's interest is unperfected as against Pike, because the early continuation statement was ineffective and the filing lapsed.","Nash Bank's interest is still perfected, because a continuation statement filed at any time before lapse extends the financing statement.","Nash Bank's interest is unperfected only as against lien creditors and still perfected as against purchasers for value, because a purchaser is bound by the original filing.","Nash Bank's interest remains perfected for another year, because a lapsed financing statement stays effective for a one-year grace period."],"a":1,"cite":"UCC §9-515(a), (c), (d)","rat":"A continuation statement may be filed only within six months before the five-year period ends.","ex":["A continuation statement may be filed only within six months before the five-year period ends. Without a timely one the filing lapses, and the interest is deemed never perfected as against a purchaser for value.","Timing matters. A continuation statement filed earlier than six months before expiration is not effective.","On lapse the interest is deemed never perfected as against a purchaser for value.","The Code provides no grace period after lapse."],"wt":["","concept","concept","concept"],"tags":{"area":"II","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A continuation statement is effective only if filed within six months before lapse; otherwise perfection lapses."}},{"i":"REG-II-C-0014","t":"Zip Bank lent $70,000 to Rena, a bakery owner, and Rena signed a security agreement giving Zip Bank a security interest in \"all equipment now owned or acquired later.\" Three months later Rena bought a new mixer with her own funds. Zip Bank has satisfied everything else needed for attachment. Which statement is most accurate?","mc":{"s":"Zip Bank lent $70,000 to Rena, a bakery owner, and Rena signed a security agreement giving Zip Bank a security interest in \"all equipment now owned or acquired later.\" Three months later Rena bought a new mixer with her own funds. Zip Bank has satisfied everything else needed for attachment. Which statement is most accurate?","d":"","o":["Zip Bank must obtain a new signed security agreement after Rena acquires the mixer before its interest can attach.","Zip Bank has no interest in the mixer, because a security interest can attach only to property the debtor owned when she signed.","Zip Bank's security interest attaches to the mixer once Rena acquires rights in it, without a new security agreement.","Zip Bank's interest attaches only if Zip Bank lends Rena additional money after she buys the mixer."],"a":3,"cite":"UCC §9-204(a)","rat":"A security agreement may create a security interest in after-acquired collateral, and the interest attaches when the debtor acquires rights in the property.","ex":["An after-acquired property clause in the original agreement is enough for later equipment.","The Code expressly permits security interests in after-acquired collateral.","A security agreement may create a security interest in after-acquired collateral, and the interest attaches when the debtor acquires rights in the property.","Value was given when the loan was made. New value is not needed for later-acquired collateral."],"wt":["concept","concept","","concept"],"tags":{"area":"II","group":"C","skill":"Application","diff":1},"asof":"2026-09-29","rl":"An after-acquired property clause makes the security interest attach when the debtor acquires rights, without a new agreement."}},{"i":"REG-II-C-0015","t":"Lark signed a $40,000 promissory note as maker payable to Metro Bank. Her friend Otto signed the note as an accommodation party, as a guarantor of payment. Without asking Otto, Metro Bank agreed in writing to extend the due date by one year. Otto proves that the extension caused him a loss of $15,000. Metro Bank sues Otto for the note. What is Otto's liability?","mc":{"s":"Lark signed a $40,000 promissory note as maker payable to Metro Bank. Her friend Otto signed the note as an accommodation party, as a guarantor of payment. Without asking Otto, Metro Bank agreed in writing to extend the due date by one year. Otto proves that the extension caused him a loss of $15,000. Metro Bank sues Otto for the note. What is Otto's liability?","d":"","o":["$0","$15,000","$25,000","$40,000"],"a":3,"cite":"UCC §3-605(b)(2); UCC §3-605(e); UCC §3-419(b), (e)","rat":"An extension discharges the secondary obligor to the extent the extension would otherwise cause a loss: $40,000 - $15,000 = $25,000.","ex":["The discharge is limited to the extent of the loss. The extension does not release him entirely.","This treats the loss as the amount he owes instead of the amount by which he is discharged.","An extension discharges the secondary obligor to the extent the extension would otherwise cause a loss: $40,000 - $15,000 = $25,000.","This ignores the discharge for the loss caused by the extension."],"wt":["concept","calc","","concept"],"tags":{"area":"II","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"An accommodation party is discharged to the extent of loss caused by the creditor's extension without consent.","calc":1,"steps":["Discharge equals the loss caused by the extension: $15,000","Remaining liability: $40,000 - $15,000 = $25,000"]}},{"i":"REG-II-C-0017","t":"Mira bought a $1,800 home theater system for her household from Circuit World on credit. She signed a security agreement giving Circuit World a purchase-money security interest in the system. Circuit World did not file a financing statement and did not take possession of the system. Which statement is most accurate about perfection?","mc":{"s":"Mira bought a $1,800 home theater system for her household from Circuit World on credit. She signed a security agreement giving Circuit World a purchase-money security interest in the system. Circuit World did not file a financing statement and did not take possession of the system. Which statement is most accurate about perfection?","d":"","o":["Circuit World's security interest is unperfected until it files a financing statement in the state.","Circuit World's security interest is perfected only if it holds the system as pledged collateral.","Circuit World's interest is perfected on attachment, because a purchase-money interest in consumer goods is perfected automatically.","Circuit World's security interest is perfected only after 20 days pass without objection from another creditor or a competing filing."],"a":3,"cite":"UCC §9-309(1)","rat":"A purchase-money security interest in consumer goods is perfected when it attaches, subject to the exception for goods covered by certain titling statutes.","ex":["Filing is the general method, but it is not required for this kind of interest.","Possession is one way to perfect but is not required for a consumer-goods purchase-money interest.","A purchase-money security interest in consumer goods is perfected when it attaches, subject to the exception for goods covered by certain titling statutes.","Perfection here is automatic on attachment, without any waiting period."],"wt":["concept","concept","","concept"],"tags":{"area":"II","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A purchase-money security interest in consumer goods is perfected automatically on attachment."}},{"i":"REG-II-C-0018","t":"Kyle bought a $10,000 motorcycle for personal use from Ridge Cycles. Ridge Finance financed the entire cash price and took a purchase-money security interest in the motorcycle. Kyle paid $6,500 of the cash price and then defaulted. Ridge Finance repossessed the motorcycle and held it for 100 days without selling it. It then told Kyle that it would keep the motorcycle in full satisfaction of the debt. Kyle had signed nothing after default. Which statement is most accurate?","mc":{"s":"Kyle bought a $10,000 motorcycle for personal use from Ridge Cycles. Ridge Finance financed the entire cash price and took a purchase-money security interest in the motorcycle. Kyle paid $6,500 of the cash price and then defaulted. Ridge Finance repossessed the motorcycle and held it for 100 days without selling it. It then told Kyle that it would keep the motorcycle in full satisfaction of the debt. Kyle had signed nothing after default. Which statement is most accurate?","d":"","o":["Ridge Finance may keep the motorcycle, because a secured party may retain collateral in full satisfaction after holding it for 90 days.","Ridge Finance may keep the motorcycle, because Kyle did not object to the proposal within 20 days.","Ridge Finance could not keep the motorcycle; with 60 percent of the cash price paid, it had to sell within 90 days after taking possession.","Ridge Finance had to sell the motorcycle within 90 days only if the sale price would have exceeded the debt."],"a":3,"cite":"UCC §9-620(e), (f)","rat":"Where a purchase-money security interest secures consumer goods and 60 percent of the cash price has been paid, the secured party that took possession must dispose of the collateral within 90 days unless the debtor and all secondary obligors agreed to a longer period in an agreement entered into and authenticated after default.","ex":["The 90-day period is a deadline to sell when 60 percent has been paid. It does not give the right to keep the collateral.","Silence does not permit retention when the 60 percent rule requires disposition and there was no post-default agreement to a longer period.","Where a purchase-money security interest secures consumer goods and 60 percent of the cash price has been paid, the secured party that took possession must dispose of the collateral within 90 days unless the debtor and all secondary obligors agreed to a longer period in an agreement entered into and authenticated after default.","The duty to dispose does not depend on whether the sale would produce a surplus."],"wt":["concept","concept","","concept"],"tags":{"area":"II","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"In consumer goods, a secured party holding 60% of the price paid must sell within 90 days and cannot keep the collateral."}},{"i":"REG-II-C-0019","t":"Mia financed a $12,000 used car for personal use with Lakeshore Credit. The principal amount of the obligation was $12,000 and the credit service charge under the contract was $2,100. After default, Lakeshore repossessed and sold the car without sending Mia the required notification of disposition. Mia proved that her actual loss from the failure was $500. What is the minimum amount Mia may recover for this failure?","mc":{"s":"Mia financed a $12,000 used car for personal use with Lakeshore Credit. The principal amount of the obligation was $12,000 and the credit service charge under the contract was $2,100. After default, Lakeshore repossessed and sold the car without sending Mia the required notification of disposition. Mia proved that her actual loss from the failure was $500. What is the minimum amount Mia may recover for this failure?","d":"","o":["$500","$1,200","$2,100","$3,300"],"a":4,"cite":"UCC §9-625(c)(2)","rat":"In a consumer-goods transaction the debtor may recover in any event not less than the credit service charge ($2,100) plus 10 percent of the principal amount ($1,200), or $3,300.","ex":["This is Mia's actual loss. The statutory minimum is larger in a consumer-goods transaction.","This is only 10 percent of the principal amount and leaves out the credit service charge.","This is only the credit service charge and leaves out 10 percent of the principal amount.","In a consumer-goods transaction the debtor may recover in any event not less than the credit service charge ($2,100) plus 10 percent of the principal amount ($1,200), or $3,300."],"wt":["calc","calc","calc",""],"tags":{"area":"II","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Consumer-goods statutory damages equal the credit service charge plus 10% of the principal amount.","calc":1,"steps":["Credit service charge $2,100","10% of principal 0.10 x $12,000 = $1,200","Minimum recovery $2,100 + $1,200 = $3,300"]}},{"i":"REG-II-C-0020","t":"Ironwood Bank holds a security interest in all present and after-acquired inventory of Delta Sports, a retailer, and filed a financing statement two years ago. On June 1, Vista Supply sold Delta $30,000 of skis on credit under a security agreement that gave Vista a purchase-money security interest in the skis, and Vista filed a financing statement that same day. Delta received the skis on June 5. Vista never sent any notification to Ironwood Bank. Who has priority in the skis?","mc":{"s":"Ironwood Bank holds a security interest in all present and after-acquired inventory of Delta Sports, a retailer, and filed a financing statement two years ago. On June 1, Vista Supply sold Delta $30,000 of skis on credit under a security agreement that gave Vista a purchase-money security interest in the skis, and Vista filed a financing statement that same day. Delta received the skis on June 5. Vista never sent any notification to Ironwood Bank. Who has priority in the skis?","d":"","o":["Vista has priority, because a purchase-money security interest perfected before the debtor receives possession defeats every earlier filed interest.","Vista has priority, because it filed within 20 days after Delta received the skis.","Ironwood Bank and Vista share the skis equally, because both filed financing statements covering the skis.","Ironwood Bank has priority, because Vista sent Ironwood no notification of its purchase-money interest before Delta got the skis."],"a":4,"cite":"UCC §9-324(b); UCC §9-322(a)(1)","rat":"A perfected purchase-money security interest in inventory has priority over a conflicting inventory security interest only if the purchase-money secured party perfects by the time the debtor receives possession and sends an authenticated notification to the holder of the conflicting interest.","ex":["That is the rule for equipment, which needs only perfection within 20 days. Inventory also requires notification to the earlier secured party.","The 20-day rule is for non-inventory collateral. For inventory, perfection must exist when the debtor receives possession, and notice is required.","Priority is decided by the rules on purchase-money interests and filing order, not by sharing equally.","A perfected purchase-money security interest in inventory has priority over a conflicting inventory security interest only if the purchase-money secured party perfects by the time the debtor receives possession and sends an authenticated notification to the holder of the conflicting interest. Vista sent no notification."],"wt":["concept","limit","concept",""],"tags":{"area":"II","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A purchase-money interest in inventory has priority only if perfected before possession and the earlier secured party is notified."}},{"i":"REG-II-C-0021","t":"Copperfield Fabrication LLC is organized under Delaware law. Its only office, plant and equipment are in Texas. Prairie Bank takes a security interest in Copperfield's equipment and wants to perfect by filing a financing statement. Where must Prairie Bank file to perfect?","mc":{"s":"Copperfield Fabrication LLC is organized under Delaware law. Its only office, plant and equipment are in Texas. Prairie Bank takes a security interest in Copperfield's equipment and wants to perfect by filing a financing statement. Where must Prairie Bank file to perfect?","d":"","o":["With the Texas filing office, because the equipment and the debtor's only office and plant are located in Texas.","With the county records of the Texas county where the equipment sits, because equipment is tangible property.","With both Delaware and Texas, because a filing in only one state perfects as to that state's collateral.","With the Delaware filing office, because a registered organization is located in its state of organization."],"a":4,"cite":"UCC §9-301(1); UCC §9-307(e)","rat":"The law of the debtor's location governs perfection by filing.","ex":["For a registered organization, location is the state of organization, not the state where its office or collateral is located.","For equipment, filing is central to the debtor's state of location, not in county real property records.","One filing in the debtor's location perfects, and a second filing in another state is not required.","The law of the debtor's location governs perfection by filing. A registered organization organized under a state's law is located in that state, so the filing belongs in the Delaware central filing office."],"wt":["concept","concept","concept",""],"tags":{"area":"II","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A registered organization is located in its state of organization, where a financing statement must be filed."}},{"i":"REG-II-C-0022","t":"On January 15 of Year 1, Harbor Bank filed a financing statement against \"Pine Ridge Crafts, Inc.\" covering all its present and after-acquired inventory, and perfected its security interest. On March 1 of Year 2, Pine Ridge changed its corporate name to \"Summit Woodworks, Inc.,\" which made the financing statement seriously misleading. Harbor Bank never amended the financing statement. Pine Ridge acquired inventory on February 1, June 15 and August 10 of Year 2. On August 20 of Year 2, in which inventory is Harbor Bank's security interest perfected by that filing?","mc":{"s":"On January 15 of Year 1, Harbor Bank filed a financing statement against \"Pine Ridge Crafts, Inc.\" covering all its present and after-acquired inventory, and perfected its security interest. On March 1 of Year 2, Pine Ridge changed its corporate name to \"Summit Woodworks, Inc.,\" which made the financing statement seriously misleading. Harbor Bank never amended the financing statement. Pine Ridge acquired inventory on February 1, June 15 and August 10 of Year 2. On August 20 of Year 2, in which inventory is Harbor Bank's security interest perfected by that filing?","d":"","o":["Only the inventory acquired on February 1, because the name change ended the financing statement's effect as to any later collateral.","All three lots of inventory, because a financing statement stays effective as to after-acquired collateral until it lapses.","None of the inventory, because a seriously misleading financing statement is ineffective for all collateral from the date of the name change.","The inventory acquired on February 1 and June 15, but not the inventory acquired on August 10."],"a":4,"cite":"UCC §9-507(c)","rat":"After a name change makes the financing statement seriously misleading, it remains effective for collateral acquired before the change or within four months after it.","ex":["The financing statement still covers collateral acquired within four months after the name change.","Once the statement becomes seriously misleading, coverage of collateral acquired more than four months later is lost unless an amendment is filed.","It remains effective for collateral acquired before the change and within four months after it.","After a name change makes the financing statement seriously misleading, it remains effective for collateral acquired before the change or within four months after it. That covers February 1 and June 15, but August 10 is more than four months after March 1."],"wt":["concept","concept","concept",""],"tags":{"area":"II","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"After a debtor's name change, a filed statement still perfects collateral acquired within four months, but not later acquisitions."}},{"i":"REG-II-C-0023","t":"Fullerton Motors lent $80,000 to Brill Bakery Inc., a business, secured by Brill's delivery truck. After default, Fullerton repossessed the truck. On October 1 it sent Brill an authenticated notification of a public sale to be held October 13. Brill argues that the notification was not sent within a reasonable time before the sale. Which statement is most accurate?","mc":{"s":"Fullerton Motors lent $80,000 to Brill Bakery Inc., a business, secured by Brill's delivery truck. After default, Fullerton repossessed the truck. On October 1 it sent Brill an authenticated notification of a public sale to be held October 13. Brill argues that the notification was not sent within a reasonable time before the sale. Which statement is most accurate?","d":"","o":["The notification was not timely, because a secured party must give at least 30 days' notice of a public sale before it sells collateral.","The notification was not timely, because in every case timeliness is judged only as a question of fact by a court.","The notification was timely only if Brill acknowledged receiving it in a signed writing before the sale date.","The notification was timely, because in a non-consumer transaction one sent after default at least 10 days before the sale qualifies."],"a":4,"cite":"UCC §9-612(a), (b)","rat":"In a transaction other than a consumer transaction, a notification of disposition sent after default and 10 days or more before the earliest time of disposition is sent within a reasonable time.","ex":["No 30-day minimum exists. The 10-day safe harbor applies to a non-consumer transaction.","The 10-day safe harbor removes the question of fact for a non-consumer transaction.","An acknowledgment from the debtor is not required.","In a transaction other than a consumer transaction, a notification of disposition sent after default and 10 days or more before the earliest time of disposition is sent within a reasonable time."],"wt":["limit","concept","concept",""],"tags":{"area":"II","group":"C","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"In a non-consumer transaction, notification of disposition sent at least 10 days before disposition is timely."}},{"i":"REG-II-C-0024","t":"Peak Signs sold a $10,000 account owed by its customer, Orin Building Supply, to Nexus Capital. Nexus sent Orin an authenticated notification that reasonably identified the account and directed Orin to pay Nexus. Two weeks later Orin paid the $10,000 to Peak Signs, which spent it. Nexus demanded payment from Orin. Which statement is most accurate?","mc":{"s":"Peak Signs sold a $10,000 account owed by its customer, Orin Building Supply, to Nexus Capital. Nexus sent Orin an authenticated notification that reasonably identified the account and directed Orin to pay Nexus. Two weeks later Orin paid the $10,000 to Peak Signs, which spent it. Nexus demanded payment from Orin. Which statement is most accurate?","d":"","o":["Orin is not discharged, because after the notification it could discharge the account only by paying Nexus.","Orin is discharged, because payment to the original creditor named in the invoice is enough to satisfy the debt.","Orin is discharged, because it paid within 30 days after the notification was sent.","Orin is discharged unless Nexus also filed a financing statement covering the account."],"a":1,"cite":"UCC §9-406(a)","rat":"Once the account debtor receives an authenticated notification of the assignment, it may discharge its obligation only by paying the assignee.","ex":["Once the account debtor receives an authenticated notification of the assignment, it may discharge its obligation only by paying the assignee.","Payment to the assignor discharges the account debtor only until the debtor receives a notification of the assignment.","There is no 30-day grace period after receipt of the notification.","Discharge turns on the notification, not on whether the assignee filed a financing statement."],"wt":["","concept","limit","concept"],"tags":{"area":"II","group":"C","skill":"Application","diff":1},"asof":"2026-09-29","rl":"After notification of assignment, an account debtor is discharged only by paying the assignee."}},{"i":"REG-II-C-0025","t":"Solano Tools sold a machine to Bay Foods for $20,000 on credit and then assigned Bay Foods' account to Crest Finance. Before Bay Foods received any notification of the assignment, it had a valid $4,500 claim against Solano arising from defects in that same sale. Bay Foods had not signed any agreement waiving its defenses against an assignee. Crest Finance sued Bay Foods for the account. How much can Crest Finance collect?","mc":{"s":"Solano Tools sold a machine to Bay Foods for $20,000 on credit and then assigned Bay Foods' account to Crest Finance. Before Bay Foods received any notification of the assignment, it had a valid $4,500 claim against Solano arising from defects in that same sale. Bay Foods had not signed any agreement waiving its defenses against an assignee. Crest Finance sued Bay Foods for the account. How much can Crest Finance collect?","d":"","o":["$4,500","$15,500","$20,000","$24,500"],"a":2,"cite":"UCC §9-404(a)(1), (b)","rat":"The assignee takes subject to the account debtor's defenses and claims arising from the same transaction, up to the amount owed.","ex":["This is the amount of Bay Foods' claim, not the amount Crest collects.","The assignee takes subject to the account debtor's defenses and claims arising from the same transaction, up to the amount owed. $20,000 less $4,500 leaves $15,500.","This ignores the account debtor's claim arising from the same transaction, which reduces what the assignee can collect.","This adds the claim to the account, but the claim reduces what the debtor owes."],"wt":["calc","","concept","calc"],"tags":{"area":"II","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"An account debtor's claim from the same transaction reduces what the assignee can collect.","calc":1,"steps":["Account $20,000","Claim arising from same sale $4,500","Collectible $20,000 - $4,500 = $15,500"]}}],"7":[{"i":"REG-II-D-0001","t":"In each month of last year, Northwind employed 35 full-time employees who averaged 30 or more hours of service per week. Its other employees, none of them seasonal, together worked 3,600 hours of service per month, and none of them worked more than 120 hours in any month. For deciding whether Northwind is an applicable large employer this year, what was its average number of full-time employees, including full-time equivalents, last year?","mc":{"s":"In each month of last year, Northwind employed 35 full-time employees who averaged 30 or more hours of service per week. Its other employees, none of them seasonal, together worked 3,600 hours of service per month, and none of them worked more than 120 hours in any month. For deciding whether Northwind is an applicable large employer this year, what was its average number of full-time employees, including full-time equivalents, last year?","d":"","o":["35","65","125","155"],"a":2,"cite":"IRC §4980H(c)(2)(A); IRC §4980H(c)(2)(E)","rat":"Part-time hours divided by 120 give full-time equivalents: 3,600 / 120 = 30.","ex":["This counts only actual full-time employees. Equivalents from part-time hours are added to the full-time count.","Part-time hours divided by 120 give full-time equivalents: 3,600 / 120 = 30. Adding the 35 full-time employees gives 65, which is at least 50, so Northwind is an applicable large employer.","This divides the 3,600 hours by 40 instead of 120 (90 equivalents) and adds 35.","This divides the 3,600 hours by 30 instead of 120 (120 equivalents) and adds 35."],"wt":["concept","","calc","calc"],"tags":{"area":"II","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Full-time equivalents are total part-time hours divided by 120 per month, added to full-time employees.","calc":1,"steps":["Full-time equivalents: 3,600 hours / 120 = 30","Total: 35 + 30 = 65","65 is at least 50, so Northwind is an applicable large employer"]}},{"i":"REG-II-D-0010","t":"Kyle's employer offered him self-only coverage that met the minimum value standard and cost less than the affordability threshold. Kyle declined it and bought a marketplace plan instead. Which statement is most accurate about his premium tax credit for those months?","mc":{"s":"Kyle's employer offered him self-only coverage that met the minimum value standard and cost less than the affordability threshold. Kyle declined it and bought a marketplace plan instead. Which statement is most accurate about his premium tax credit for those months?","d":"","o":["Kyle is eligible for the credit, because it is available to any individual who buys marketplace coverage.","Kyle is eligible for the credit, because declining the employer plan puts him in the position of having no offer of coverage.","Kyle is eligible for half of the credit, because employer eligibility only reduces the credit by 50 percent.","Kyle is generally not eligible for the credit, because he was eligible for affordable employer coverage with minimum value."],"a":4,"cite":"IRC §36B(c)(2)(B); IRC §36B(c)(2)(C)","rat":"A month in which the individual is eligible for affordable, minimum-value employer-sponsored coverage generally does not qualify for the credit, even if the individual declines it.","ex":["Buying marketplace coverage is necessary but not sufficient. Eligibility for affordable employer coverage generally disqualifies the month.","Eligibility for the employer plan is what matters. Declining it does not restore the credit.","There is no automatic 50 percent reduction. The month either qualifies or does not.","A month in which the individual is eligible for affordable, minimum-value employer-sponsored coverage generally does not qualify for the credit, even if the individual declines it."],"wt":["concept","concept","concept",""],"tags":{"area":"II","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A taxpayer eligible for affordable, minimum-value employer coverage generally cannot claim the premium tax credit."}},{"i":"REG-II-D-0013","t":"In each of the 12 months of the year, Cobalt Inc., an applicable large employer with 120 full-time employees, offered no health coverage to its employees. In each month, 4 full-time employees enrolled in marketplace plans and received a premium tax credit. For this problem assume the applicable payment amount is $3,000 per full-time employee for the year, spread evenly by month. What is Cobalt Inc.'s assessable payment for the year?","mc":{"s":"In each of the 12 months of the year, Cobalt Inc., an applicable large employer with 120 full-time employees, offered no health coverage to its employees. In each month, 4 full-time employees enrolled in marketplace plans and received a premium tax credit. For this problem assume the applicable payment amount is $3,000 per full-time employee for the year, spread evenly by month. What is Cobalt Inc.'s assessable payment for the year?","d":"","o":["$12,000","$210,000","$270,000","$360,000"],"a":3,"cite":"IRC §4980H(a); IRC §4980H(c)(1), (c)(2)(D)","rat":"The payment is the applicable payment amount times the full-time employees after subtracting the first 30: (120 - 30) x $3,000 = $270,000.","ex":["This counts only the 4 employees who received credits. The payment is based on all full-time employees less 30.","This subtracts 50 employees instead of 30, using the size threshold for being a large employer.","The payment is the applicable payment amount times the full-time employees after subtracting the first 30: (120 - 30) x $3,000 = $270,000.","This multiplies all 120 full-time employees and omits the reduction of 30."],"wt":["calc","limit","","calc"],"tags":{"area":"II","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"An employer offering no coverage owes a payment on full-time employees minus 30, times the annual amount.","calc":1,"steps":["Full-time employees less 30: 120 - 30 = 90","Payment: 90 x $3,000 = $270,000"]}},{"i":"REG-II-D-0014","t":"In each month of the year, Dunmore Inc., an applicable large employer, had 40 full-time employees and offered coverage that was not affordable. In each month, 12 full-time employees enrolled in marketplace plans and received a premium tax credit. For this problem assume that, for the year, the amount for each employee who receives a credit is $4,500 and the applicable payment amount is $3,000 per full-time employee, each spread evenly by month. What is Dunmore Inc.'s assessable payment for the year?","mc":{"s":"In each month of the year, Dunmore Inc., an applicable large employer, had 40 full-time employees and offered coverage that was not affordable. In each month, 12 full-time employees enrolled in marketplace plans and received a premium tax credit. For this problem assume that, for the year, the amount for each employee who receives a credit is $4,500 and the applicable payment amount is $3,000 per full-time employee, each spread evenly by month. What is Dunmore Inc.'s assessable payment for the year?","d":"","o":["$30,000","$36,000","$54,000","$120,000"],"a":1,"cite":"IRC §4980H(b)(1), (b)(2); IRC §4980H(c)(1), (c)(2)(D)","rat":"The credit-based amount is 12 x $4,500 = $54,000, but it is capped at the amount that would apply if no coverage were offered: (40 - 30) x $3,000 = $30,000.","ex":["The credit-based amount is 12 x $4,500 = $54,000, but it is capped at the amount that would apply if no coverage were offered: (40 - 30) x $3,000 = $30,000. The lesser is $30,000.","This multiplies the 12 credit recipients by the $3,000 applicable payment amount instead of the $4,500 amount, and ignores the cap.","This is the uncapped credit-based amount (12 x $4,500). It exceeds the overall limitation.","This applies $3,000 to all 40 full-time employees, with neither the 30-employee reduction nor the correct base."],"wt":["","calc","calc","calc"],"tags":{"area":"II","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"For unaffordable coverage the payment is per credit recipient but capped at the no-coverage amount.","calc":1,"steps":["Credit-based amount: 12 x $4,500 = $54,000","Overall limit: (40 - 30) x $3,000 = $30,000","Payment is the lesser: $30,000"]}},{"i":"REG-II-D-0015","t":"Halcyon Corp. withheld income and FICA taxes of $48,000 from employees' pay in the third quarter but used the cash to pay suppliers and did not pay it to the IRS. Rhea, the chief financial officer, decided which bills were paid and knew the taxes were unpaid. The corporation later had no assets. Which statement is most accurate about the IRS's trust fund recovery penalty proposal?","mc":{"s":"Halcyon Corp. withheld income and FICA taxes of $48,000 from employees' pay in the third quarter but used the cash to pay suppliers and did not pay it to the IRS. Rhea, the chief financial officer, decided which bills were paid and knew the taxes were unpaid. The corporation later had no assets. Which statement is most accurate about the IRS's trust fund recovery penalty proposal?","d":"","o":["Rhea can be personally liable for a penalty equal to the $48,000, if she was required to collect and pay over the tax and willfully failed to.","Only the corporation is liable, because an officer cannot be personally liable for a corporation's payroll taxes, even one who controlled payments.","Rhea is liable for only half of the tax, because the penalty is shared with the employees whose pay was withheld.","Rhea is liable only if the IRS first obtains a criminal conviction against her for failing to pay over the withheld taxes."],"a":1,"cite":"IRC §6672(a); IRC §6671(b)","rat":"A person required to collect, account for and pay over a tax who willfully fails to do so is liable for a penalty equal to the tax not paid over, and a corporate officer under a duty to act can be such a person.","ex":["A person required to collect, account for and pay over a tax who willfully fails to do so is liable for a penalty equal to the tax not paid over, and a corporate officer under a duty to act can be such a person.","The statute reaches an officer of a corporation who is under a duty to perform the act.","The penalty equals the full amount of the tax not paid over and is not shared with the employees.","The civil penalty does not depend on a criminal conviction. It requires a preliminary notice."],"wt":["","concept","concept","concept"],"tags":{"area":"II","group":"D","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"A responsible officer who willfully fails to pay over withheld taxes is personally liable for the trust fund recovery penalty."}},{"i":"REG-II-D-0026","t":"Sunrise Orchards employs 30 full-time employees all year. Each year it hires 40 seasonal pickers for a harvest of 100 days. During those 100 days its workforce is 70 full-time employees, and 40 of them are seasonal workers as defined by the Secretary of Labor. Sunrise had the same pattern in the previous calendar year. Is Sunrise treated as an applicable large employer for the current year?","mc":{"s":"Sunrise Orchards employs 30 full-time employees all year. Each year it hires 40 seasonal pickers for a harvest of 100 days. During those 100 days its workforce is 70 full-time employees, and 40 of them are seasonal workers as defined by the Secretary of Labor. Sunrise had the same pattern in the previous calendar year. Is Sunrise treated as an applicable large employer for the current year?","d":"","o":["Yes, because its workforce exceeded 50 full-time employees on at least one day during the year.","No, because its workforce exceeded 50 for 120 days or fewer, and the excess employees were seasonal workers.","Yes, because the exception applies only if the excess lasts 90 days or fewer, and Sunrise's lasted 100 days.","No, but only if Sunrise offers minimum essential coverage to all 70 employees during the harvest."],"a":2,"cite":"IRC §4980H(c)(2)(B)","rat":"An employer is not treated as employing more than 50 full-time employees if the workforce exceeded 50 for 120 days or fewer during the year and the employees above 50 during that period were seasonal workers.","ex":["Exceeding 50 on some days is not enough. The seasonal worker exception applies when the excess lasts 120 days or fewer and consists of seasonal workers.","An employer is not treated as employing more than 50 full-time employees if the workforce exceeded 50 for 120 days or fewer during the year and the employees above 50 during that period were seasonal workers.","The period is 120 days or fewer, not 90 days.","The exception affects whether Sunrise is an applicable large employer. It is not conditioned on offering coverage."],"wt":["concept","","limit","concept"],"tags":{"area":"II","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"The seasonal worker exception excludes an employer from large-employer status if its workforce exceeds 50 for 120 days or fewer due to seasonal workers."}}],"8":[{"i":"REG-II-D-0002","t":"Maya, a graphic designer, works for Brightline Inc. Brightline sets her hours, requires her to work at its office on its computers, gives step-by-step instructions on how each design is made, and can end the arrangement at will. Her contract calls her an independent contractor, and Brightline files a Form 1099-NEC for her. How is Maya most likely classified for employment tax purposes?","mc":{"s":"Maya, a graphic designer, works for Brightline Inc. Brightline sets her hours, requires her to work at its office on its computers, gives step-by-step instructions on how each design is made, and can end the arrangement at will. Her contract calls her an independent contractor, and Brightline files a Form 1099-NEC for her. How is Maya most likely classified for employment tax purposes?","d":"","o":["An independent contractor, because her signed contract labels her one and both parties agreed to that label.","An employee, because Brightline has the right to direct the details and means of her work.","An independent contractor, because Brightline chose to report her pay on a Form 1099-NEC.","An independent contractor, because graphic design is a skilled profession that requires training."],"a":2,"cite":"Treas. Reg. §31.3121(d)-1(a)(3); Treas. Reg. §31.3121(d)-1(c)(1); Treas. Reg. §31.3121(d)-1(c)(2)","rat":"Under the common-law control test, the right to direct how the work is done points to employment, and the parties' label is not controlling.","ex":["Labels do not control if the relationship is in substance employment.","Under the common-law control test, the right to direct how the work is done points to employment, and the parties' label is not controlling.","The form filed does not decide classification. The control relationship does.","Skill alone does not make a worker independent. Control is the focus."],"wt":["concept","","concept","concept"],"tags":{"area":"II","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Worker classification turns on the right to control details and means of the work, not labels or skill."}},{"i":"REG-II-D-0025","t":"Assume that each of the following workers is an independent contractor under the common law control test. Which worker is nevertheless treated as an employee for FICA purposes under the statutory categories, as long as the contract calls for substantially all of the services to be performed personally?","mc":{"s":"Assume that each of the following workers is an independent contractor under the common law control test. Which worker is nevertheless treated as an employee for FICA purposes under the statutory categories, as long as the contract calls for substantially all of the services to be performed personally?","d":"","o":["Neal, a self-employed attorney who advises the company on contracts for a fee.","Omar, a freelance web developer who builds one website for a fixed fee.","Marta, who works full time selling life insurance for one insurance company.","Pia, who owns a truck and hauls freight for many customers on a per-load basis."],"a":3,"cite":"IRC §3121(d)(3)(B); IRC §3121(d)(2)","rat":"A full-time life insurance salesperson is one of the statutory categories of employees, treated as an employee for FICA even if not an employee under the common law.","ex":["Providing professional services as an independent business is not one of the statutory employee categories.","A single-project developer does not fall within the statutory categories, and an isolated transaction is excluded.","A full-time life insurance salesperson is one of the statutory categories of employees, treated as an employee for FICA even if not an employee under the common law.","The driver category covers agent-drivers who distribute specified products such as meat, vegetables, bakery goods or beverages for a principal."],"wt":["concept","concept","","concept"],"tags":{"area":"II","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Statutory employees include full-time life insurance salespersons and certain agent-drivers, while independent professionals and one-project freelancers are not."}}],"9":[{"i":"REG-II-D-0003","t":"Zenith Corp. has stopped operating and wants to wind up and sell its assets. Paul, an individual with a steady salary, wants to keep his home and repay his debts over time under a court-approved plan. Each is considering bankruptcy. Which statement is most accurate?","mc":{"s":"Zenith Corp. has stopped operating and wants to wind up and sell its assets. Paul, an individual with a steady salary, wants to keep his home and repay his debts over time under a court-approved plan. Each is considering bankruptcy. Which statement is most accurate?","d":"","o":["Zenith should file chapter 13, because chapter 13 is the liquidation proceeding designed for corporations that stop operating.","Paul cannot use chapter 13, because a repayment plan is available only to corporations that have regular income.","Paul must file chapter 7, because chapter 13 is limited to businesses that continue to operate after filing.","Zenith may liquidate under chapter 7 with a trustee, and Paul may qualify for chapter 13 as an individual with regular income."],"a":4,"cite":"11 U.S.C. §109(e); 11 U.S.C. §704(a)(1); 11 U.S.C. §727","rat":"Chapter 7 is a liquidation run by a trustee.","ex":["Chapter 13 is not a corporate liquidation. It is an individual repayment proceeding.","Chapter 13 is limited to individuals with regular income, not corporations.","Chapter 13 is designed for individuals with regular income and does not require an operating business.","Chapter 7 is a liquidation run by a trustee. Chapter 13 is a repayment plan open to individuals with regular income."],"wt":["concept","concept","concept",""],"tags":{"area":"II","group":"D","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Chapter 7 liquidates entities and individuals, while chapter 13 is a repayment plan only for individuals with regular income."}},{"i":"REG-II-D-0004","t":"Lena received a chapter 7 discharge in a case she filed in February 2020. In January 2026 she files a new chapter 7 case. Assume no other ground for denying discharge applies. Which statement is most accurate?","mc":{"s":"Lena received a chapter 7 discharge in a case she filed in February 2020. In January 2026 she files a new chapter 7 case. Assume no other ground for denying discharge applies. Which statement is most accurate?","d":"","o":["Lena will likely be denied a discharge, because her earlier chapter 7 case began within eight years before this one.","Lena will receive a discharge, because each chapter 7 case entitles the debtor to its own separate discharge.","Lena will receive a discharge, because the bar on repeat chapter 7 discharges lasts only six years from filing.","Lena may not file a second chapter 7 case, because the Code permits only one such case for a debtor."],"a":1,"cite":"11 U.S.C. §727(a)(8)","rat":"A prior discharge under section 727 in a case commenced within eight years bars a new chapter 7 discharge.","ex":["A prior discharge under section 727 in a case commenced within eight years bars a new chapter 7 discharge.","The eight-year bar limits repeat chapter 7 discharges.","The chapter 7 to chapter 7 bar is eight years. Six years relates to a prior chapter 13 discharge.","She may file. The effect is on the discharge, not on the right to file."],"wt":["","concept","limit","concept"],"tags":{"area":"II","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A chapter 7 discharge is barred if the debtor received a prior chapter 7 discharge in a case filed within eight years."}},{"i":"REG-II-D-0005","t":"Quinn owes Vendor $8,000 for goods bought last year. Vendor sued Quinn, and a hearing is set. Quinn then filed a voluntary bankruptcy petition. Vendor keeps pursuing the lawsuit. Which statement is most accurate?","mc":{"s":"Quinn owes Vendor $8,000 for goods bought last year. Vendor sued Quinn, and a hearing is set. Quinn then filed a voluntary bankruptcy petition. Vendor keeps pursuing the lawsuit. Which statement is most accurate?","d":"","o":["Vendor may continue, because the stay covers only lawsuits that were filed after the bankruptcy petition.","Vendor may continue, because the stay begins only after the bankruptcy court holds a hearing on the petition.","Vendor may continue, because the automatic stay applies only to collection efforts by secured creditors.","Vendor must stop, because the petition automatically stays the lawsuit on the pre-petition claim, subject to exceptions."],"a":4,"cite":"11 U.S.C. §362(a)(1)","rat":"Filing a petition generally stays actions to recover claims that arose before the case began.","ex":["The stay covers continuation of pending actions.","The stay arises automatically on filing.","The stay protects the debtor against collection by creditors generally.","Filing a petition generally stays actions to recover claims that arose before the case began."],"wt":["concept","concept","concept",""],"tags":{"area":"II","group":"D","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A bankruptcy petition automatically stays collection actions on pre-petition claims."}},{"i":"REG-II-D-0016","t":"Jorge, an individual, filed a voluntary chapter 7 petition on October 1. On August 15, Jorge paid $12,000 to Kovac, an unrelated unsecured creditor, on an old loan that was past due. Jorge was insolvent, and the payment let Kovac receive more than Kovac would have received in the chapter 7 case. The payment was not in the ordinary course of business, and no statutory exception applies. Which statement is most accurate?","mc":{"s":"Jorge, an individual, filed a voluntary chapter 7 petition on October 1. On August 15, Jorge paid $12,000 to Kovac, an unrelated unsecured creditor, on an old loan that was past due. Jorge was insolvent, and the payment let Kovac receive more than Kovac would have received in the chapter 7 case. The payment was not in the ordinary course of business, and no statutory exception applies. Which statement is most accurate?","d":"","o":["The trustee may not avoid the payment, because Kovac was not an insider and the reach-back for non-insiders is only 30 days.","The trustee may avoid the payment as a preference, because it paid an old debt within 90 days while Jorge was insolvent.","The trustee may avoid the payment only if Kovac knew that Jorge was insolvent when he was paid.","The trustee may not avoid the payment, because paying a valid debt cannot be a preference."],"a":2,"cite":"11 U.S.C. §547(b), (f)","rat":"The elements are a transfer to a creditor for an antecedent debt while insolvent, within 90 days (a year for insiders), that lets the creditor receive more than in chapter 7.","ex":["The reach-back for a non-insider is 90 days, and August 15 to October 1 is within it.","The elements are a transfer to a creditor for an antecedent debt while insolvent, within 90 days (a year for insiders), that lets the creditor receive more than in chapter 7. Insolvency is presumed in the 90 days.","The creditor's knowledge is not an element of a preference.","A payment on a valid antecedent debt is exactly what a preference is, unless an exception applies."],"wt":["concept","","concept","concept"],"tags":{"area":"II","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A trustee may avoid a payment on an old debt made within 90 days before bankruptcy while insolvent."}},{"i":"REG-II-D-0017","t":"Ruth received a chapter 7 discharge. Before filing, she owed each of the following unsecured debts. Which debt most likely survived the discharge?","mc":{"s":"Ruth received a chapter 7 discharge. Before filing, she owed each of the following unsecured debts. Which debt most likely survived the discharge?","d":"","o":["A $6,000 judgment for money Ruth obtained from a friend by falsely promising to repay it while planning not to","A $9,000 credit card balance run up for ordinary household expenses over several years","A $14,000 unpaid hospital bill for treatment Ruth received two years before filing","A $3,500 judgment for unpaid rent on an apartment Ruth leased and vacated last year"],"a":1,"cite":"11 U.S.C. §523(a)(2)(A)","rat":"A discharge does not cover a debt for money obtained by false pretenses, a false representation, or actual fraud.","ex":["A discharge does not cover a debt for money obtained by false pretenses, a false representation, or actual fraud.","Ordinary consumer credit card debt without fraud or another exception is discharged.","An unpaid medical bill is an ordinary unsecured debt and is discharged.","Unpaid rent is an ordinary contract debt and is discharged."],"wt":["","concept","concept","concept"],"tags":{"area":"II","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Debts obtained by fraud are excepted from a chapter 7 discharge, while ordinary consumer, medical and rent debts are discharged."}},{"i":"REG-II-D-0019","t":"On March 3, Carlos filed a chapter 7 petition. Before the filing, a state prosecutor had charged him with fraud in an unrelated matter, and several creditors had started collection efforts. Which of the following may continue without violating the automatic stay?","mc":{"s":"On March 3, Carlos filed a chapter 7 petition. Before the filing, a state prosecutor had charged him with fraud in an unrelated matter, and several creditors had started collection efforts. Which of the following may continue without violating the automatic stay?","d":"","o":["A bank's lawsuit to collect a $15,000 personal loan","A collection agency's phone calls demanding payment of a medical bill","A creditor's pending garnishment of Carlos's wages for a consumer debt","The state prosecutor's pending criminal case against Carlos"],"a":4,"cite":"11 U.S.C. §362(a), (b)(1)","rat":"A bankruptcy petition does not stay the commencement or continuation of a criminal action or proceeding against the debtor.","ex":["A civil action to recover a claim against the debtor is stayed.","Acts to collect a claim against the debtor arising before the case are stayed.","Garnishment to collect a pre-petition consumer debt is stayed. Only certain support obligations are excepted.","A bankruptcy petition does not stay the commencement or continuation of a criminal action or proceeding against the debtor."],"wt":["concept","concept","concept",""],"tags":{"area":"II","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The automatic stay does not stop criminal proceedings against the debtor."}},{"i":"REG-II-D-0020","t":"On February 1 of Year 1, Gus, who was insolvent, gave his brother a boat worth $25,000 in exchange for $2,000. Gus filed a voluntary chapter 7 petition on December 1 of Year 2. The trustee wants to recover the boat for the estate. Which statement is most accurate?","mc":{"s":"On February 1 of Year 1, Gus, who was insolvent, gave his brother a boat worth $25,000 in exchange for $2,000. Gus filed a voluntary chapter 7 petition on December 1 of Year 2. The trustee wants to recover the boat for the estate. Which statement is most accurate?","d":"","o":["The trustee may avoid the transfer only if the trustee proves that Gus intended to hinder or defraud his creditors.","The trustee may not avoid the transfer, because transfers can be reached only if made within one year before the petition.","The trustee may avoid the transfer only if it was made within 90 days before the petition, as with preferences to non-insiders.","The trustee may avoid the transfer as constructively fraudulent: it was made within 2 years, for less than reasonably equivalent value, while Gus was insolvent."],"a":4,"cite":"11 U.S.C. §548(a)(1)(A), (B)","rat":"A trustee may avoid a transfer made within 2 years before the petition if the debtor received less than reasonably equivalent value and was insolvent at the time.","ex":["Actual intent is one ground. Constructive fraud is a separate ground that does not require intent.","The reach-back for these fraudulent transfers is 2 years. This transfer was 22 months before the petition.","The 90-day period is for preferences to non-insiders, which is a different rule.","A trustee may avoid a transfer made within 2 years before the petition if the debtor received less than reasonably equivalent value and was insolvent at the time. Intent to defraud need not be proved."],"wt":["concept","limit","limit",""],"tags":{"area":"II","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A transfer within two years for less than reasonably equivalent value while insolvent is constructively fraudulent."}},{"i":"REG-II-D-0021","t":"The chapter 7 estate of Kiln Corp. has $60,000 available for distribution after secured creditors were paid from their collateral. Allowed claims are: chapter 7 administrative expenses of $10,000; income taxes that qualify as priority claims of $20,000; timely filed general unsecured claims of $100,000; and tardily filed general unsecured claims of $50,000 that do not qualify for any exception. How much does a timely filed general unsecured creditor with a $20,000 claim receive?","mc":{"s":"The chapter 7 estate of Kiln Corp. has $60,000 available for distribution after secured creditors were paid from their collateral. Allowed claims are: chapter 7 administrative expenses of $10,000; income taxes that qualify as priority claims of $20,000; timely filed general unsecured claims of $100,000; and tardily filed general unsecured claims of $50,000 that do not qualify for any exception. How much does a timely filed general unsecured creditor with a $20,000 claim receive?","d":"","o":["$4,000","$6,000","$10,000","$12,000"],"a":2,"cite":"11 U.S.C. §726(a)(1), (a)(2), (a)(3); 11 U.S.C. §507(a)(2), (a)(8)","rat":"Administrative expenses and priority taxes are paid first ($30,000), leaving $30,000 for the $100,000 of timely general claims, or 30 percent.","ex":["This puts the tardily filed claims in the same class as timely claims ($30,000 over $150,000, or 20 percent).","Administrative expenses and priority taxes are paid first ($30,000), leaving $30,000 for the $100,000 of timely general claims, or 30 percent. 30 percent of $20,000 is $6,000, and tardy claims are paid later.","This pays administrative expenses but treats the priority taxes as if they were paid with the general claims.","This ignores the priority of the administrative expenses and taxes ($60,000 over $100,000, or 60 percent)."],"wt":["calc","","calc","calc"],"tags":{"area":"II","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Chapter 7 distributions follow priority, and late-filed claims rank behind timely general claims.","calc":1,"steps":["Administrative $10,000 and priority taxes $20,000 paid first = $30,000","Remaining $60,000 - $30,000 = $30,000","Timely general claims $100,000, so 30,000 / 100,000 = 30%","$20,000 x 30% = $6,000"]}},{"i":"REG-II-D-0022","t":"Farah is an individual with regular income who files a chapter 13 petition. Her current monthly income multiplied by 12 is below the median family income for her state. Her plan does not propose to pay unsecured creditors in full. Which statement is most accurate about her applicable commitment period?","mc":{"s":"Farah is an individual with regular income who files a chapter 13 petition. Her current monthly income multiplied by 12 is below the median family income for her state. Her plan does not propose to pay unsecured creditors in full. Which statement is most accurate about her applicable commitment period?","d":"","o":["Three years, because her current monthly income is below the state median.","Five years, because the commitment period is 5 years for below-median debtors and 3 years for above-median debtors.","Five years, because every chapter 13 plan must last five years when unsecured creditors are not paid in full.","One year, because a debtor with below-median income may choose any plan length the debtor prefers."],"a":1,"cite":"11 U.S.C. §1325(b)(4)","rat":"The applicable commitment period is 3 years, or not less than 5 years if current monthly income is at or above the state median, unless the plan pays unsecured claims in full over a shorter period.","ex":["The applicable commitment period is 3 years, or not less than 5 years if current monthly income is at or above the state median, unless the plan pays unsecured claims in full over a shorter period.","This reverses the rule. Above-median debtors have the longer period.","The length depends on the debtor's income compared with the state median.","The Code sets the applicable commitment period at 3 years for a below-median debtor unless the plan pays unsecured claims in full over a shorter time."],"wt":["","concept","concept","limit"],"tags":{"area":"II","group":"D","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"A below-median-income chapter 13 debtor has a three-year applicable commitment period; above-median debtors have five."}}],"10":[{"i":"REG-II-D-0006","t":"Torvo Corp., a U.S. issuer, hired a local consultant. Torvo's manager knew the consultant would pass $50,000 to the relative of a foreign ministry official to win a government construction contract. Torvo recorded the $50,000 as consulting fees. Which statement is most accurate under the Foreign Corrupt Practices Act?","mc":{"s":"Torvo Corp., a U.S. issuer, hired a local consultant. Torvo's manager knew the consultant would pass $50,000 to the relative of a foreign ministry official to win a government construction contract. Torvo recorded the $50,000 as consulting fees. Which statement is most accurate under the Foreign Corrupt Practices Act?","d":"","o":["Torvo violated neither set of provisions, because the consultant and not Torvo made the payment.","Torvo likely violated both the anti-bribery provisions and the books-and-records provisions.","Torvo violated only the anti-bribery provisions, because recording a payment is not covered by the Act.","Torvo violated only the books-and-records provisions, because the payment went to the official's relative."],"a":2,"cite":"15 U.S.C. §78dd-1(a); 15 U.S.C. §78m(b)(2)(A)","rat":"Payment through an intermediary with knowledge that it will reach an official to obtain business is covered, and mislabeling the payment breaches the accounting provisions.","ex":["Payments through intermediaries with knowledge are covered.","Payment through an intermediary with knowledge that it will reach an official to obtain business is covered, and mislabeling the payment breaches the accounting provisions.","Issuers must keep books that accurately reflect transactions in reasonable detail.","A payment intended for an official through a relative or conduit can still violate the anti-bribery rule."],"wt":["concept","","concept","concept"],"tags":{"area":"II","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A payment knowingly passed through an intermediary to a foreign official violates FCPA anti-bribery and books-and-records provisions."}},{"i":"REG-II-D-0007","t":"An employee of Avex Corp., a U.S. issuer, paid a foreign clerk $100 to speed up the routine stamping of a permit application Avex was already entitled to, and recorded it accurately as a facilitation payment. Which statement is most accurate?","mc":{"s":"An employee of Avex Corp., a U.S. issuer, paid a foreign clerk $100 to speed up the routine stamping of a permit application Avex was already entitled to, and recorded it accurately as a facilitation payment. Which statement is most accurate?","d":"","o":["Any payment to a foreign official violates the anti-bribery provisions, whatever its amount, purpose or recording.","The payment is lawful only if it is left out of the company's books and records so that it is not disclosed.","The exception fails, because a payment of only $100 is too small to qualify as speeding a routine governmental action.","The anti-bribery rules except payments to speed routine governmental action, and accurate recording satisfies the books rule."],"a":4,"cite":"15 U.S.C. §78dd-1(b); 15 U.S.C. §78dd-1(f)(3); 15 U.S.C. §78m(b)(2)(A)","rat":"Expediting a routine action falls in the exception, and accurate recording avoids an accounting violation.","ex":["The routine-governmental-action exception applies.","Omitting it would create a books-and-records violation.","The exception turns on the purpose of the payment, not its size.","Expediting a routine action falls in the exception, and accurate recording avoids an accounting violation. Local law may still prohibit the payment."],"wt":["concept","concept","concept",""],"tags":{"area":"II","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The FCPA excepts small facilitating payments for routine governmental action, which must be accurately recorded."}},{"i":"REG-II-D-0018","t":"Bristol Tools LLC is a privately held company organized in Ohio with its principal place of business there. It has no securities registered in the United States. Its sales director, Gwen, e-mailed a foreign customs official from Ohio, offering him $15,000 to approve an import license for Bristol Tools. Which statement is most accurate?","mc":{"s":"Bristol Tools LLC is a privately held company organized in Ohio with its principal place of business there. It has no securities registered in the United States. Its sales director, Gwen, e-mailed a foreign customs official from Ohio, offering him $15,000 to approve an import license for Bristol Tools. Which statement is most accurate?","d":"","o":["Neither is covered, because the law applies only to companies whose securities are registered in the United States.","Bristol Tools and Gwen can be liable under the federal foreign bribery law, because it covers domestic concerns as well as issuers.","Neither is covered, because the offer was made by e-mail from Ohio rather than in the foreign country where the official works.","They are covered only if the official actually approves the license, because an offer alone is not a violation of the statute."],"a":2,"cite":"15 U.S.C. §78dd-2(a), (h)(1)","rat":"The statute prohibits corrupt offers or payments to a foreign official by a domestic concern, which includes a business organized in a state or with its principal place of business in the United States, even if it is not an issuer.","ex":["Domestic concerns that are not issuers are covered by a separate provision.","The statute prohibits corrupt offers or payments to a foreign official by a domestic concern, which includes a business organized in a state or with its principal place of business in the United States, even if it is not an issuer.","Use of the mails or interstate commerce in furtherance of the offer is the jurisdictional link for a domestic concern.","An offer, promise or authorization of payment is itself covered."],"wt":["concept","","concept","concept"],"tags":{"area":"II","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The FCPA covers domestic concerns as well as issuers, using interstate commerce as the link."}},{"i":"REG-II-D-0028","t":"Pacific Devices, a U.S. issuer, invited three mid-level officials of a state-owned foreign hospital to visit its U.S. factory for two days to see a demonstration of its imaging equipment. Pacific paid only their economy airfare and hotel rooms for the two days. It gave no cash and paid for no side trips or family members. Which statement is most accurate under the anti-bribery provisions of the Foreign Corrupt Practices Act?","mc":{"s":"Pacific Devices, a U.S. issuer, invited three mid-level officials of a state-owned foreign hospital to visit its U.S. factory for two days to see a demonstration of its imaging equipment. Pacific paid only their economy airfare and hotel rooms for the two days. It gave no cash and paid for no side trips or family members. Which statement is most accurate under the anti-bribery provisions of the Foreign Corrupt Practices Act?","d":"","o":["The payments violate the statute, because any item of value given to a foreign official is prohibited by the statute.","The payments are permitted because they are facilitating payments to speed up routine governmental action.","The payments are not a violation, because they were reasonable, bona fide expenses directly related to a product demonstration.","The payments violate the statute unless the hospital officials repay Pacific after they return home."],"a":3,"cite":"15 U.S.C. §78dd-1(c)(2); 15 U.S.C. §78dd-1(f)(1)(A)","rat":"Payments that are reasonable and bona fide expenditures, such as travel and lodging, directly related to the promotion, demonstration or explanation of products are an affirmative defense.","ex":["The statute prohibits corrupt payments to obtain or retain business and provides an affirmative defense for reasonable, bona fide, directly related expenses.","Facilitating payments are a different exception for routine governmental actions. These payments qualify under the expenditure defense.","Payments that are reasonable and bona fide expenditures, such as travel and lodging, directly related to the promotion, demonstration or explanation of products are an affirmative defense.","Repayment is not required for a reasonable bona fide expenditure that is directly related to a demonstration."],"wt":["concept","concept","","concept"],"tags":{"area":"II","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The FCPA affirmative defense covers reasonable, bona fide expenses directly related to product demonstration."}},{"i":"REG-II-D-0029","t":"Halberd Corp. is a U.S. issuer. It had no written process for approving cash payments to overseas sales agents. Over two years the manager of its Asia office paid $300,000 to agents, and every payment was recorded accurately in the books. An investigation found no evidence that any agent passed money to a foreign official. Which statement is most accurate under the Foreign Corrupt Practices Act?","mc":{"s":"Halberd Corp. is a U.S. issuer. It had no written process for approving cash payments to overseas sales agents. Over two years the manager of its Asia office paid $300,000 to agents, and every payment was recorded accurately in the books. An investigation found no evidence that any agent passed money to a foreign official. Which statement is most accurate under the Foreign Corrupt Practices Act?","d":"","o":["Halberd may still violate the accounting provisions, because an issuer must maintain a system of internal accounting controls that gives reasonable assurance that transactions are authorized by management, whether or not bribery occurred.","Halberd has no exposure, because the accounting provisions apply only if a bribe has actually been paid.","Halberd may violate the accounting provisions only if the payments went to foreign officials.","Halberd has no exposure, because the accounting provisions apply only to companies with foreign subsidiaries."],"a":1,"cite":"15 U.S.C. §78m(b)(2)(B)","rat":"The internal accounting controls requirement applies to issuers independently of the anti-bribery provisions.","ex":["The internal accounting controls requirement applies to issuers independently of the anti-bribery provisions. The absence of any bribery does not remove the duty to maintain a system that provides reasonable assurance of management authorization.","The accounting provisions stand on their own and do not require proof of a bribe.","The internal controls duty does not depend on who received the payments.","The provisions apply to issuers, not only to issuers with foreign subsidiaries."],"wt":["","concept","concept","concept"],"tags":{"area":"II","group":"D","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"An FCPA issuer must maintain adequate internal accounting controls, and violation does not require proof of a bribe."}}],"11":[{"i":"REG-II-D-0008","t":"Wren works for Crest Inc. and notices that no federal unemployment tax is deducted from her paychecks. She asks whether that is an error. Which statement is most accurate?","mc":{"s":"Wren works for Crest Inc. and notices that no federal unemployment tax is deducted from her paychecks. She asks whether that is an error. Which statement is most accurate?","d":"","o":["It is not an error, because FUTA tax is imposed on the employer and is not withheld from an employee's wages.","It is an error, because FUTA tax must be withheld from wages just like the employee share of FICA tax.","It is an error, because FUTA tax is shared equally between the employer and the employee.","It is not an error, because FUTA tax applies only to independent contractors and not to employees at all."],"a":1,"cite":"IRC §3301","rat":"FUTA is an excise tax on employers, and employers pay it without deducting it from wages.","ex":["FUTA is an excise tax on employers, and employers pay it without deducting it from wages.","The employee share of FICA is withheld. FUTA has no employee share.","This describes the FICA structure. FUTA is borne by the employer alone.","FUTA applies to wages paid to employees. Independent contractors are outside it."],"wt":["","concept","concept","concept"],"tags":{"area":"II","group":"D","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"FUTA tax is imposed on the employer alone and is not withheld from employees."}},{"i":"REG-II-D-0009","t":"Sam earns $1,000 in gross wages for a weekly pay period, well below any annual wage limit. He gave his employer a signed note asking that no Social Security or Medicare tax be withheld from his pay. Assume the employee-share rates are 6.2 percent for Social Security and 1.45 percent for Medicare. What amount of employee FICA tax must the employer withhold from this paycheck?","mc":{"s":"Sam earns $1,000 in gross wages for a weekly pay period, well below any annual wage limit. He gave his employer a signed note asking that no Social Security or Medicare tax be withheld from his pay. Assume the employee-share rates are 6.2 percent for Social Security and 1.45 percent for Medicare. What amount of employee FICA tax must the employer withhold from this paycheck?","d":"","o":["$14.50","$38.25","$62.00","$76.50"],"a":4,"cite":"IRC §3101(a), (b)(1); IRC §3102(a)","rat":"The employer must deduct both parts of the employee share, and an employee cannot waive it: $1,000 x 6.2% = $62.00 plus $1,000 x 1.45% = $14.50.","ex":["This is the Medicare part only. The Social Security part must also be withheld.","This is half of the combined $76.50, as if Sam's request cut the withholding in half. The employee share cannot be waived in whole or in part.","This is the Social Security part only. The Medicare part must also be withheld.","The employer must deduct both parts of the employee share, and an employee cannot waive it: $1,000 x 6.2% = $62.00 plus $1,000 x 1.45% = $14.50."],"wt":["calc","concept","calc",""],"tags":{"area":"II","group":"D","skill":"Application","diff":1},"asof":"2026-09-29","rl":"The employee's Social Security and Medicare withholding cannot be waived by the employee.","calc":1,"steps":["Social Security part: $1,000 x 6.2% = $62.00","Medicare part: $1,000 x 1.45% = $14.50","Total withheld: $62.00 + $14.50 = $76.50; the request to skip withholding has no effect"]}},{"i":"REG-II-D-0011","t":"Marta is married and earned $230,000 in wages from Gale Corp. this year. Her spouse earned $100,000 from a different employer. Gale Corp. paid Marta evenly through the year. What amount of additional Medicare tax must Gale Corp. withhold from Marta's wages for the year?","mc":{"s":"Marta is married and earned $230,000 in wages from Gale Corp. this year. Her spouse earned $100,000 from a different employer. Gale Corp. paid Marta evenly through the year. What amount of additional Medicare tax must Gale Corp. withhold from Marta's wages for the year?","d":"","o":["$0","$270","$1,170","$2,070"],"a":2,"cite":"IRC §3101(b)(2); IRC §3102(f)(1)","rat":"The employer withholds 0.9 percent of wages over $200,000 and may disregard the spouse's wages: 0.9% x ($230,000 - $200,000) = $270.","ex":["This uses the $250,000 joint-return threshold. Employer withholding starts at $200,000 for every employee.","The employer withholds 0.9 percent of wages over $200,000 and may disregard the spouse's wages: 0.9% x ($230,000 - $200,000) = $270.","This adds the spouse's $100,000 to Marta's wages, which the employer may disregard: 0.9% x $130,000.","This applies 0.9 percent to all $230,000 of wages instead of only the excess over $200,000."],"wt":["limit","","calc","calc"],"tags":{"area":"II","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Employers withhold 0.9% additional Medicare tax on wages above $200,000, regardless of filing status or spouse's wages.","calc":1,"steps":["Employer threshold: $200,000, spouse's wages disregarded","Excess wages: $230,000 - $200,000 = $30,000","Withholding: 0.9% x $30,000 = $270"]}},{"i":"REG-II-D-0012","t":"Plume Co. paid $19,000 of wages to each of its 8 employees during the year. Plume Co. paid all of its required state unemployment contributions on time, at least 5.4 percent of the first $7,000 of each employee's wages. Ignore any state credit reduction. What is Plume Co.'s federal unemployment tax for the year after the credit for state contributions?","mc":{"s":"Plume Co. paid $19,000 of wages to each of its 8 employees during the year. Plume Co. paid all of its required state unemployment contributions on time, at least 5.4 percent of the first $7,000 of each employee's wages. Ignore any state credit reduction. What is Plume Co.'s federal unemployment tax for the year after the credit for state contributions?","d":"","o":["$336","$912","$3,360","$9,120"],"a":1,"cite":"IRC §3301; IRC §3302(a), (c)(1); IRC §3306(b)(1)","rat":"Taxable wages are 8 x $7,000 = $56,000.","ex":["Taxable wages are 8 x $7,000 = $56,000. The tax is 6.0 percent, less a 5.4 percent credit for timely state contributions, a net 0.6 percent: $56,000 x 0.6% = $336.","This applies the net 0.6 percent to all $152,000 of wages instead of only the first $7,000 per employee.","This applies the full 6.0 percent to $56,000 and omits the credit for state contributions.","This applies 6.0 percent to all $152,000 of wages, with neither the wage base nor the credit."],"wt":["","calc","calc","calc"],"tags":{"area":"II","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"FUTA's net 0.6% rate applies only to the first $7,000 of each employee's wages after the state credit.","calc":1,"steps":["FUTA wage base: 8 x $7,000 = $56,000","Net rate: 6.0% - 5.4% = 0.6%","Tax: $56,000 x 0.6% = $336"]}},{"i":"REG-II-D-0023","t":"Larkin Co. was required to deposit $40,000 of employment taxes by September 15. It made the deposit on September 27, 12 days late, without reasonable cause. The IRS had sent no notice or demand. What is the failure-to-deposit penalty?","mc":{"s":"Larkin Co. was required to deposit $40,000 of employment taxes by September 15. It made the deposit on September 27, 12 days late, without reasonable cause. The IRS had sent no notice or demand. What is the failure-to-deposit penalty?","d":"","o":["$800","$2,000","$4,000","$6,000"],"a":2,"cite":"IRC §6656(a), (b)(1)(A)","rat":"A deposit that is more than 5 days but not more than 15 days late is penalized at 5 percent.","ex":["This is 2 percent, the rate for a deposit no more than 5 days late.","A deposit that is more than 5 days but not more than 15 days late is penalized at 5 percent. 5 percent of $40,000 is $2,000.","This is 10 percent, the rate for a deposit more than 15 days late.","This is 15 percent, the rate that applies only if the tax remains unpaid after a notice or demand."],"wt":["limit","","limit","limit"],"tags":{"area":"II","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A late employment tax deposit penalty is 5% if 6 to 15 days late, 2% within 5 days, and 10% if later.","calc":1,"steps":["Days late 12, which is more than 5 and not more than 15","Rate 5%","Penalty 5% x $40,000 = $2,000"]}},{"i":"REG-II-D-0024","t":"Orbit Media treated Drew as an independent contractor and paid him $50,000, filing Form 1099-NEC to report the payments. The IRS later determined that Drew was an employee. Assume Orbit did not intentionally disregard the requirements, and that the reduced-rate rules for misclassified workers apply. Under those rules, the employer's liability for withholding on wages is 1.5 percent of wages, and its liability for the employee share of FICA is 20 percent of that share. The employer share of FICA is 7.65 percent, and the employee share is also 7.65 percent. What is Orbit's total liability for income tax withholding and both shares of FICA?","mc":{"s":"Orbit Media treated Drew as an independent contractor and paid him $50,000, filing Form 1099-NEC to report the payments. The IRS later determined that Drew was an employee. Assume Orbit did not intentionally disregard the requirements, and that the reduced-rate rules for misclassified workers apply. Under those rules, the employer's liability for withholding on wages is 1.5 percent of wages, and its liability for the employee share of FICA is 20 percent of that share. The employer share of FICA is 7.65 percent, and the employee share is also 7.65 percent. What is Orbit's total liability for income tax withholding and both shares of FICA?","d":"","o":["$1,515","$5,340","$6,855","$8,400"],"a":2,"cite":"IRC §3509(a), (b), (c)","rat":"Income tax withholding is 1.5 percent of $50,000, or $750.","ex":["This leaves out the employer's own share of FICA ($3,825).","Income tax withholding is 1.5 percent of $50,000, or $750. The employee FICA share is 20 percent of $3,825, or $765. The employer share is $3,825. The total is $5,340.","This uses the higher rates (3 percent and 40 percent) that apply when required information returns were not filed.","This charges the full employee share of FICA ($3,825) instead of 20 percent of it."],"wt":["calc","","limit","calc"],"tags":{"area":"II","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Section 3509 reduced rates apply to misclassified workers when Forms 1099 were filed, using 1.5% of wages and 20% of employee FICA.","calc":1,"steps":["Withholding 1.5% x $50,000 = $750","Employee FICA share 7.65% x $50,000 = $3,825; 20% of it = $765","Employer FICA share 7.65% x $50,000 = $3,825","Total $750 + $765 + $3,825 = $5,340"]}}],"12":[{"i":"REG-II-E-0001","t":"Ella and Sam agreed to run a food truck together, to co-own it and to share profits. They signed nothing and filed nothing with the state. The truck's supplier is owed $6,000 for goods bought for the business. Which statement is most accurate?","mc":{"s":"Ella and Sam agreed to run a food truck together, to co-own it and to share profits. They signed nothing and filed nothing with the state. The truck's supplier is owed $6,000 for goods bought for the business. Which statement is most accurate?","d":"","o":["A general partnership was likely formed without any filing, and Ella and Sam can each be liable for the $6,000 debt.","No entity exists, because the co-owners filed nothing with the state, so the supplier cannot collect from Ella or Sam.","A limited liability company was formed automatically, so neither Ella nor Sam is personally liable.","A limited partnership was formed, so both Ella and Sam are shielded from personal liability."],"a":1,"cite":"RUPA (1997, amended 2013) §202(a); RUPA (1997, amended 2013) §306(a)","rat":"Two persons carrying on a business for profit as co-owners form a partnership whether or not they intend to, and partners are generally jointly and severally liable.","ex":["Two persons carrying on a business for profit as co-owners form a partnership whether or not they intend to, and partners are generally jointly and severally liable.","The association is itself a partnership, and its partners can be liable.","An LLC requires a state filing.","A limited partnership requires a filed certificate and at least one general partner."],"wt":["","concept","concept","concept"],"tags":{"area":"II","group":"E","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Co-owners who carry on a business for profit and share profits form a general partnership without any filing."}},{"i":"REG-II-E-0003","t":"Rosa is the sole shareholder of Fresco Inc., a properly formed corporation whose articles say nothing about shareholder liability. Fresco cannot pay $40,000 it owes a landlord. Rosa signed no guarantee and did nothing wrongful. Which statement is most accurate?","mc":{"s":"Rosa is the sole shareholder of Fresco Inc., a properly formed corporation whose articles say nothing about shareholder liability. Fresco cannot pay $40,000 it owes a landlord. Rosa signed no guarantee and did nothing wrongful. Which statement is most accurate?","d":"","o":["Rosa is liable for the whole $40,000, because a sole shareholder answers for the corporation's debts when it cannot pay them.","The landlord generally cannot collect from Rosa personally, because a shareholder is not liable for debts except through the shareholder's own acts.","Rosa is liable for half, because shareholders and the corporation share corporate debts equally when it is insolvent.","Rosa is liable up to the dividends she has received, because dividends must be returned to the corporation's creditors."],"a":2,"cite":"RMBCA §6.22(b)","rat":"Limited liability protects shareholders unless the articles provide otherwise or the shareholder's own conduct creates liability.","ex":["Owning all the shares does not by itself remove the shield.","Limited liability protects shareholders unless the articles provide otherwise or the shareholder's own conduct creates liability.","There is no automatic sharing rule.","That is not the general rule. Limited liability applies absent her own conduct."],"wt":["concept","","concept","concept"],"tags":{"area":"II","group":"E","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A shareholder is not personally liable for corporate debts merely as a shareholder, even if sole owner."}},{"i":"REG-II-E-0005","t":"Lumen LLC is governed by a statute based on the Uniform Limited Liability Company Act (2006). Its members never held annual meetings or kept minutes. Lumen defaulted on a $30,000 loan, and the lender sued member Zed personally, arguing that the LLC ignored formalities. Which statement is most accurate?","mc":{"s":"Lumen LLC is governed by a statute based on the Uniform Limited Liability Company Act (2006). Its members never held annual meetings or kept minutes. Lumen defaulted on a $30,000 loan, and the lender sued member Zed personally, arguing that the LLC ignored formalities. Which statement is most accurate?","d":"","o":["Zed is liable, because the LLC failed to observe formalities such as annual meetings and written minutes of decisions.","Zed is liable, because members are jointly liable for LLC loans unless the lender has agreed otherwise in writing.","Zed is generally not personally liable, because a member is not liable merely as a member and ignored formalities are no ground.","Zed is liable unless the operating agreement contains a clause that expressly limits member liability for debts."],"a":3,"cite":"ULLCA (2006) §304(a), (b)","rat":"The Act treats the company's debts as its own and says ignored formalities are not a ground for imposing liability on a member.","ex":["The Act expressly rejects that ground.","The default is a liability shield.","The Act treats the company's debts as its own and says ignored formalities are not a ground for imposing liability on a member.","The shield does not depend on such a clause."],"wt":["concept","concept","","concept"],"tags":{"area":"II","group":"E","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"A member of an LLC is not liable for LLC debts merely as a member, and ignoring formalities is not a ground for liability."}},{"i":"REG-II-E-0007","t":"The incorporators of Halden Inc. signed its articles of incorporation on March 1. The initial directors met on March 5. The articles were filed with the state on March 10, and the first shares were issued on March 12. Assume no delayed effective date was specified. When did Halden's corporate existence begin?","mc":{"s":"The incorporators of Halden Inc. signed its articles of incorporation on March 1. The initial directors met on March 5. The articles were filed with the state on March 10, and the first shares were issued on March 12. Assume no delayed effective date was specified. When did Halden's corporate existence begin?","d":"","o":["March 10, when the articles of incorporation were filed with the state.","March 1, when the incorporators signed the articles of incorporation, before anything reached the state.","March 5, when the initial directors held their first meeting.","March 12, when the corporation issued its first shares to investors."],"a":1,"cite":"RMBCA §2.03(a)","rat":"Unless a delayed effective date is specified, corporate existence begins when the articles are filed.","ex":["Unless a delayed effective date is specified, corporate existence begins when the articles are filed.","Signing alone does not create the corporation. Filing does.","Organizational meetings follow incorporation and do not create it.","Issuing shares is a later step. Existence begins earlier, at filing."],"wt":["","concept","concept","concept"],"tags":{"area":"II","group":"E","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A corporation's existence begins when the articles of incorporation are filed with the state."}},{"i":"REG-II-E-0014","t":"Lex, Mona and Nils operate a bookstore as a general partnership at will with no agreement about its duration. Nils gives the partnership written notice that he is withdrawing immediately. Which statement is most accurate about the effect under the Uniform Partnership Act (1997) as last amended in 2013?","mc":{"s":"Lex, Mona and Nils operate a bookstore as a general partnership at will with no agreement about its duration. Nils gives the partnership written notice that he is withdrawing immediately. Which statement is most accurate about the effect under the Uniform Partnership Act (1997) as last amended in 2013?","d":"","o":["The partnership continues unchanged with Nils as a partner, because a partner cannot dissolve a partnership at will by giving notice alone.","The partnership is dissolved and must be wound up, because a partner's express will to withdraw from a partnership at will triggers dissolution.","The partnership dissolves only after a court enters an order approving Nils's withdrawal from the bookstore partnership.","The partnership dissolves only if Lex and Mona vote to wind up the business."],"a":2,"cite":"RUPA (1997, amended 2013) §801(1); RUPA (1997, amended 2013) §601(1)","rat":"In a partnership at will, dissolution occurs when the partnership knows of a partner's express will to withdraw, and the business must then be wound up.","ex":["Notice of a partner's express will to withdraw is an event that causes dissolution in a partnership at will.","In a partnership at will, dissolution occurs when the partnership knows of a partner's express will to withdraw, and the business must then be wound up.","No court order is required for this event. A court order is a separate ground for dissolution.","A vote of the remaining partners is the rule for a partnership for a definite term, not a partnership at will."],"wt":["concept","","concept","concept"],"tags":{"area":"II","group":"E","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"A partner's express will to withdraw from a partnership at will causes dissolution and winding up."}},{"i":"REG-II-E-0015","t":"On February 1, Hana and Cole signed a $9,000 supply order in the name of \"Bloom Florals, Inc.\" Both knew that the articles of incorporation had not yet been filed. The articles were filed on February 20, but the corporation never adopted the order. The supplier sued Hana and Cole. Which statement is most accurate?","mc":{"s":"On February 1, Hana and Cole signed a $9,000 supply order in the name of \"Bloom Florals, Inc.\" Both knew that the articles of incorporation had not yet been filed. The articles were filed on February 20, but the corporation never adopted the order. The supplier sued Hana and Cole. Which statement is most accurate?","d":"","o":["Neither is liable, because the later filing of the articles relates back and shields them from liability for the earlier order.","Hana and Cole are jointly and severally liable, because they acted for a corporation knowing there was no incorporation.","Each is liable only for half of the $9,000, because the two acted together for the same business.","They are liable only if the supplier proves that they intended to deceive it about the corporation's existence."],"a":2,"cite":"MBCA §2.04","rat":"All persons purporting to act as or on behalf of a corporation, knowing there was no incorporation, are jointly and severally liable for liabilities created while so acting.","ex":["Corporate existence begins on filing, and the liability rule applies to acts done while they knew there was no incorporation.","All persons purporting to act as or on behalf of a corporation, knowing there was no incorporation, are jointly and severally liable for liabilities created while so acting.","The liability is joint and several, so the supplier may collect the whole from either.","Their knowledge that no incorporation existed is the element. Intent to deceive is not required."],"wt":["concept","","concept","concept"],"tags":{"area":"II","group":"E","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Persons who act as a corporation knowing there was no incorporation are jointly and severally liable."}}],"13":[{"i":"REG-II-E-0002","t":"Kai is a limited partner in a limited partnership formed under the Revised Uniform Limited Partnership Act. He votes on a proposed amendment to the partnership agreement and on admitting a new limited partner, and does nothing else in management. A creditor of the partnership seeks to hold Kai liable as a general partner. Which statement is most accurate?","mc":{"s":"Kai is a limited partner in a limited partnership formed under the Revised Uniform Limited Partnership Act. He votes on a proposed amendment to the partnership agreement and on admitting a new limited partner, and does nothing else in management. A creditor of the partnership seeks to hold Kai liable as a general partner. Which statement is most accurate?","d":"","o":["Kai is likely not liable as a general partner, because voting on those matters is a listed safe activity.","Kai is liable for all partnership debts, because any voting is control of the business.","Kai is liable only for debts incurred after the vote, because voting starts general partner liability going forward.","Kai is protected only if he owns less than 10 percent of the partnership interests."],"a":1,"cite":"RULPA (1985) §303(a), (b)(6)","rat":"The Act lists voting on amendments and on admission of a limited partner among activities that do not amount to taking part in control.","ex":["The Act lists voting on amendments and on admission of a limited partner among activities that do not amount to taking part in control.","The Act lists specific voting matters as safe.","The vote does not create general partner liability at all.","The Act contains no ownership threshold for these activities."],"wt":["","concept","concept","limit"],"tags":{"area":"II","group":"E","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A limited partner does not become liable as a general partner by voting on listed safe matters such as amending the agreement."}},{"i":"REG-II-E-0004","t":"Ines, a director of Corvane Inc., voted for a headquarters relocation after reviewing management's reports and questioning executives. She honestly believed it served Corvane's best interests. The plan later lost money. Which statement is most accurate about her standard of conduct?","mc":{"s":"Ines, a director of Corvane Inc., voted for a headquarters relocation after reviewing management's reports and questioning executives. She honestly believed it served Corvane's best interests. The plan later lost money. Which statement is most accurate about her standard of conduct?","d":"","o":["She is not necessarily in breach, because the standard turns on good faith, reasonable belief and care, not results.","She breached her duty, because the relocation plan lost money for Corvane after the board approved it.","She breached her duty unless the shareholders also approved the relocation plan before the board voted.","Her only duty runs to the largest shareholder, so she owes nothing to the corporation itself or to the others."],"a":1,"cite":"RMBCA §8.30(a), (b); RMBCA §8.01(b)","rat":"The standard of conduct focuses on how the director acted, not on whether the decision turned out well.","ex":["The standard of conduct focuses on how the director acted, not on whether the decision turned out well.","A poor outcome alone does not establish a breach.","Board decisions do not need shareholder approval to satisfy the standard.","The duty concerns the best interests of the corporation."],"wt":["","concept","concept","concept"],"tags":{"area":"II","group":"E","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"A director satisfies the standard of conduct by acting in good faith, with reasonable belief and care, regardless of poor outcomes."}},{"i":"REG-II-E-0006","t":"Grace is the general partner and Al and Bo are limited partners of Harbor LP, formed under the Revised Uniform Limited Partnership Act. Harbor owes an outside supplier $90,000 and lacks assets to pay. Neither limited partner has taken part in control. Whom can the supplier reach personally?","mc":{"s":"Grace is the general partner and Al and Bo are limited partners of Harbor LP, formed under the Revised Uniform Limited Partnership Act. Harbor owes an outside supplier $90,000 and lacks assets to pay. Neither limited partner has taken part in control. Whom can the supplier reach personally?","d":"","o":["Only Al and Bo, because limited partners fund the business and so answer for its debts to outside suppliers.","Only Grace, because a general partner is liable to outsiders and non-controlling limited partners are not.","No one, because a limited partnership shields all of its partners from the supplier's claim for payment.","Grace, Al and Bo equally, because every partner shares each partnership debt in equal parts with the others."],"a":2,"cite":"RULPA (1985) §403(b); RULPA (1985) §303(a)","rat":"The general partner is personally liable to outsiders, while limited partners who do not take part in control are not.","ex":["Limited partners are generally not liable unless they take part in control.","The general partner is personally liable to outsiders, while limited partners who do not take part in control are not.","At least one general partner remains liable.","Limited partners who stay out of control are not liable for the obligations."],"wt":["concept","","concept","concept"],"tags":{"area":"II","group":"E","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A limited partnership's general partner is liable to outsiders, while non-controlling limited partners are not."}},{"i":"REG-II-E-0008","t":"Al and Bea formed a general partnership by conduct, with no agreement, written or oral, about how to share partnership distributions. Al contributed $60,000 of capital and Bea contributed $20,000. The partnership earned a $50,000 profit in its first year and distributed all of it to the partners. How much of the distribution is Bea entitled to receive, absent any contrary agreement?","mc":{"s":"Al and Bea formed a general partnership by conduct, with no agreement, written or oral, about how to share partnership distributions. Al contributed $60,000 of capital and Bea contributed $20,000. The partnership earned a $50,000 profit in its first year and distributed all of it to the partners. How much of the distribution is Bea entitled to receive, absent any contrary agreement?","d":"","o":["$12,500","$20,000","$25,000","$50,000"],"a":3,"cite":"RUPA (1997, amended 2013) §401(a)","rat":"Absent a contrary agreement, each partner is entitled to an equal share of the partnership distributions regardless of capital contributed: $50,000 / 2 = $25,000.","ex":["This splits the distribution in proportion to capital (25 percent of $50,000). The default rule ignores contribution size.","This is Bea's capital contribution, not her share of the distribution.","Absent a contrary agreement, each partner is entitled to an equal share of the partnership distributions regardless of capital contributed: $50,000 / 2 = $25,000.","This is the entire distribution, as if Bea were the only partner entitled to share."],"wt":["calc","calc","","calc"],"tags":{"area":"II","group":"E","skill":"Remembering & Understanding","diff":2},"asof":"2026-09-29","rl":"Absent agreement, partners share distributions equally regardless of capital contributions.","calc":1,"steps":["Default rule: profits shared equally","Two partners: $50,000 / 2 = $25,000 each"]}},{"i":"REG-II-E-0009","t":"Sable Corp. has one class of voting stock, 100,000 shares outstanding, and no special quorum or voting rules in its articles or bylaws. At the annual meeting, holders of 60,000 shares are present. On a proposal to approve a stock incentive plan, which is not an election of directors, 24,000 shares vote for, 22,000 vote against, and 14,000 abstain. Under the default statutory rules, what is the result?","mc":{"s":"Sable Corp. has one class of voting stock, 100,000 shares outstanding, and no special quorum or voting rules in its articles or bylaws. At the annual meeting, holders of 60,000 shares are present. On a proposal to approve a stock incentive plan, which is not an election of directors, 24,000 shares vote for, 22,000 vote against, and 14,000 abstain. Under the default statutory rules, what is the result?","d":"","o":["The plan is not approved, because it did not receive the vote of a majority of all shares outstanding, which would be more than 50,000.","The plan is approved, because a quorum exists and the votes cast for the plan exceed the votes cast against it.","The plan is not approved, because it did not receive the vote of a majority of the shares present.","The plan is not approved, because the 14,000 abstentions are counted as votes against it, which makes 36,000 against."],"a":2,"cite":"MBCA (3rd ed.) §7.25(a), (c)","rat":"A majority of the votes entitled to be cast is a quorum, and action is approved if the votes cast in favor exceed the votes cast against.","ex":["The default standard compares votes cast for and against, not a majority of outstanding shares.","A majority of the votes entitled to be cast is a quorum, and action is approved if the votes cast in favor exceed the votes cast against. Abstentions are not votes cast.","The default standard is not a majority of shares present. Here 24,000 exceeds 22,000.","Abstentions are not votes cast, so they count neither for nor against."],"wt":["concept","","concept","concept"],"tags":{"area":"II","group":"E","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"By default, shareholder action passes if a quorum exists and votes cast for exceed votes cast against, with abstentions not counted."}},{"i":"REG-II-E-0010","t":"Talon Corp.'s assets have a fair value of $900,000, and its liabilities total $500,000. Its articles create preferred stock with a $150,000 liquidation preference that is superior to the common stock, and the articles do not permit ignoring it. The board proposes a distribution to the common shareholders. Assume Talon Corp. will still be able to pay its debts as they come due after the distribution. What is the largest distribution the board may make to the common shareholders?","mc":{"s":"Talon Corp.'s assets have a fair value of $900,000, and its liabilities total $500,000. Its articles create preferred stock with a $150,000 liquidation preference that is superior to the common stock, and the articles do not permit ignoring it. The board proposes a distribution to the common shareholders. Assume Talon Corp. will still be able to pay its debts as they come due after the distribution. What is the largest distribution the board may make to the common shareholders?","d":"","o":["$150,000","$250,000","$400,000","$750,000"],"a":2,"cite":"MBCA (3rd ed.) §6.40(c)(2)","rat":"After the distribution, assets must be at least liabilities plus the superior liquidation preference: $900,000 - $500,000 - $150,000 = $250,000.","ex":["This is the liquidation preference itself, not the amount left after subtracting liabilities and the preference.","After the distribution, assets must be at least liabilities plus the superior liquidation preference: $900,000 - $500,000 - $150,000 = $250,000.","This subtracts liabilities only and ignores the superior liquidation preference.","This subtracts only the preference and ignores the $500,000 of liabilities."],"wt":["calc","","calc","calc"],"tags":{"area":"II","group":"E","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"On liquidation, preferred liquidation preference is paid after liabilities and before common shareholders.","calc":1,"steps":["Assets $900,000 must remain at least liabilities plus preference","Maximum distribution: $900,000 - $500,000 - $150,000 = $250,000"]}},{"i":"REG-II-E-0012","t":"Ira, Jo and Kim run a hardware store as a general partnership under the default partnership rules, with no agreement on voting. Ira and Jo want to amend the partnership agreement so that Ira and Jo each take 40 percent of distributions and Kim takes 20 percent. Kim objects. Which statement is most accurate?","mc":{"s":"Ira, Jo and Kim run a hardware store as a general partnership under the default partnership rules, with no agreement on voting. Ira and Jo want to amend the partnership agreement so that Ira and Jo each take 40 percent of distributions and Kim takes 20 percent. Kim objects. Which statement is most accurate?","d":"","o":["The amendment can be adopted by Ira and Jo, because a majority of the partners decides every partnership matter.","The amendment can be adopted by Ira and Jo, because the partners with the largest capital contributions decide amendments to the agreement.","The amendment cannot be adopted over Kim's objection, because an amendment to the partnership agreement requires the consent of all the partners.","The amendment cannot be adopted unless a court approves the new distribution percentages."],"a":3,"cite":"RUPA (1997, amended 2013) §401(h), (k)","rat":"An amendment to the partnership agreement, like an act outside the ordinary course of business, requires the affirmative vote or consent of all the partners.","ex":["Majority rule applies to ordinary-course differences, not to amending the partnership agreement.","Default voting is per partner, not weighted by capital.","An amendment to the partnership agreement, like an act outside the ordinary course of business, requires the affirmative vote or consent of all the partners. Only ordinary-course differences go to a majority.","Court approval is not part of amending the agreement. Unanimous consent is enough."],"wt":["concept","concept","","concept"],"tags":{"area":"II","group":"E","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Amending a general partnership agreement requires the consent of all partners."}},{"i":"REG-II-E-0013","t":"A general partnership that was not a limited liability partnership has sold all its assets for $90,000 in winding up, and it owes creditors $150,000 on obligations incurred while all three partners were partners. Under the partnership agreement, Abel takes 50 percent of distributions, Brix 30 percent and Cole 20 percent. Cole cannot contribute anything, and Abel and Brix can pay. Under the Uniform Partnership Act (1997) as last amended in 2013, how much must Brix contribute in total?","mc":{"s":"A general partnership that was not a limited liability partnership has sold all its assets for $90,000 in winding up, and it owes creditors $150,000 on obligations incurred while all three partners were partners. Under the partnership agreement, Abel takes 50 percent of distributions, Brix 30 percent and Cole 20 percent. Cole cannot contribute anything, and Abel and Brix can pay. Under the Uniform Partnership Act (1997) as last amended in 2013, how much must Brix contribute in total?","d":"","o":["$18,000","$20,000","$22,500","$24,000"],"a":3,"cite":"RUPA (1997, amended 2013) §806(a), (c)","rat":"The $60,000 shortfall is shared 50/30/20: Brix owes $18,000 and Cole's $12,000 is reallocated between Abel and Brix in the ratio 50 to 30: $18,000 + $12,000 x 30/80 = $22,500.","ex":["This is Brix's original 30 percent share and ignores the additional contribution needed because Cole fails to pay.","This splits the $60,000 shortfall equally among three partners instead of by distribution shares.","The $60,000 shortfall is shared 50/30/20: Brix owes $18,000 and Cole's $12,000 is reallocated between Abel and Brix in the ratio 50 to 30: $18,000 + $12,000 x 30/80 = $22,500.","This splits Cole's $12,000 equally between Abel and Brix rather than in proportion to their 50 and 30 shares."],"wt":["calc","calc","","calc"],"tags":{"area":"II","group":"E","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"In winding up, partners share losses in proportion to their profit shares, and a defaulting partner's share is reallocated proportionally.","calc":1,"steps":["Shortfall: $150,000 - $90,000 = $60,000","Brix's first share: 30% x $60,000 = $18,000; Cole's share: 20% x $60,000 = $12,000","Cole's $12,000 reallocated to Abel and Brix in the ratio 50 to 30: Brix pays $12,000 x 30/80 = $4,500","Total for Brix: $18,000 + $4,500 = $22,500"]}},{"i":"REG-II-E-0016","t":"Rubin Corp. has 100,000 shares outstanding, one class of voting stock. Its articles are silent on cumulative voting and do not limit removal of directors to cause. At a special meeting called for the stated purpose of removing director Sloan, 60,000 shares are represented. Votes are cast 25,000 to remove Sloan and 20,000 against, and 15,000 shares abstain. Which statement is most accurate?","mc":{"s":"Rubin Corp. has 100,000 shares outstanding, one class of voting stock. Its articles are silent on cumulative voting and do not limit removal of directors to cause. At a special meeting called for the stated purpose of removing director Sloan, 60,000 shares are represented. Votes are cast 25,000 to remove Sloan and 20,000 against, and 15,000 shares abstain. Which statement is most accurate?","d":"","o":["Sloan is removed, because votes cast to remove (25,000) exceed votes cast against removal (20,000).","Sloan is not removed, because removal requires the vote of a majority of all 100,000 outstanding shares.","Sloan is not removed, because shareholders may remove a director only for cause.","Sloan is not removed, because abstentions count as votes against removal when a quorum is present."],"a":1,"cite":"MBCA §8.08(a), (c), (d)","rat":"With no cumulative voting, shareholders may remove a director with or without cause if the votes cast to remove exceed the votes cast not to remove, at a meeting called for that purpose.","ex":["With no cumulative voting, shareholders may remove a director with or without cause if the votes cast to remove exceed the votes cast not to remove, at a meeting called for that purpose. Abstentions are not votes cast.","The test compares votes cast for and against removal. It is not a majority of outstanding shares.","The default rule permits removal with or without cause unless the articles limit removal to cause.","Abstentions are not votes cast, so the comparison is 25,000 for and 20,000 against."],"wt":["","concept","concept","concept"],"tags":{"area":"II","group":"E","skill":"Application","diff":2},"asof":"2026-09-29","rl":"By default, directors may be removed with or without cause when votes cast to remove exceed votes cast against."}},{"i":"REG-II-E-0017","t":"Tolan Inc.'s articles of incorporation are silent on preemptive rights. Bea owns 20 percent of the shares. The board approves issuing new shares for cash to an outside investor. Bea demands the right to buy 20 percent of the new shares to keep her ownership share. Which statement is most accurate?","mc":{"s":"Tolan Inc.'s articles of incorporation are silent on preemptive rights. Bea owns 20 percent of the shares. The board approves issuing new shares for cash to an outside investor. Bea demands the right to buy 20 percent of the new shares to keep her ownership share. Which statement is most accurate?","d":"","o":["Bea has the right, because every shareholder may maintain a proportionate share unless the bylaws deny it.","Bea has no such right, because shareholders have no preemptive right unless the articles provide one.","Bea has the right, because she owns more than 10 percent of the shares.","Bea has the right only if she gives written notice within 30 days after the board approves the issuance."],"a":2,"cite":"MBCA §6.30(a)","rat":"Shareholders have no preemptive right to acquire unissued shares except to the extent the articles of incorporation so provide.","ex":["The default is no preemptive right, and the exception depends on the articles, not the bylaws.","Shareholders have no preemptive right to acquire unissued shares except to the extent the articles of incorporation so provide.","The size of her holding does not create a preemptive right.","A notice period does not create a right. The right must exist in the articles."],"wt":["concept","","concept","concept"],"tags":{"area":"II","group":"E","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Shareholders have no preemptive right unless the articles of incorporation provide one."}},{"i":"REG-II-E-0018","t":"Vireo Corp. will elect three directors at its annual meeting. Its articles are silent on cumulative voting. Wu owns 34,000 of the 100,000 shares, and the other holders together own 66,000 shares. Wu says that cumulative voting would let him elect one of the three directors. Which statement is most accurate?","mc":{"s":"Vireo Corp. will elect three directors at its annual meeting. Its articles are silent on cumulative voting. Wu owns 34,000 of the 100,000 shares, and the other holders together own 66,000 shares. Wu says that cumulative voting would let him elect one of the three directors. Which statement is most accurate?","d":"","o":["Wu may cumulate his votes, because cumulative voting applies unless the articles deny it.","Wu may cumulate his votes if he gives the corporation notice at least 48 hours before the meeting.","Wu has no right to cumulate, so holders of a majority of the shares can elect all three directors.","Wu may cumulate his votes because he owns more than one third of the shares."],"a":3,"cite":"MBCA §7.28(a), (b)","rat":"Shareholders have no right to cumulate votes for directors unless the articles so provide, and directors are elected by a plurality of votes cast.","ex":["The default is no cumulative voting. The articles must grant it.","The 48-hour notice matters only where the articles already authorize cumulative voting.","Shareholders have no right to cumulate votes for directors unless the articles so provide, and directors are elected by a plurality of votes cast. A majority group can therefore elect every seat.","Ownership above a fraction of the shares does not create the right without a provision in the articles."],"wt":["concept","concept","","concept"],"tags":{"area":"II","group":"E","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Cumulative voting is not available unless the articles provide for it."}},{"i":"REG-II-E-0019","t":"Marlin Inc. has a fixed board of 9 directors. Its articles and bylaws do not change the default quorum or voting rules. Five directors attend a properly called board meeting. On a resolution to approve a $200,000 equipment purchase, 3 vote yes and 2 vote no. Which statement is most accurate?","mc":{"s":"Marlin Inc. has a fixed board of 9 directors. Its articles and bylaws do not change the default quorum or voting rules. Five directors attend a properly called board meeting. On a resolution to approve a $200,000 equipment purchase, 3 vote yes and 2 vote no. Which statement is most accurate?","d":"","o":["The resolution passes, because a quorum is 5 of the 9 directors and 3 is a majority of the 5 present.","The resolution fails, because it needs the affirmative vote of a majority of all 9 directors, which is 5.","The resolution fails, because a quorum requires two thirds of the fixed number of directors.","The resolution passes only if a majority of the shareholders also ratify it after the meeting."],"a":1,"cite":"MBCA §8.24(a), (c)","rat":"A quorum is a majority of the fixed number of directors, which is 5.","ex":["A quorum is a majority of the fixed number of directors, which is 5. If a quorum is present, the affirmative vote of a majority of the directors present is the act of the board.","The default requires a majority of the directors present when a quorum exists.","The default quorum is a majority of the fixed number of directors.","Board action of this kind does not need shareholder ratification."],"wt":["","concept","limit","concept"],"tags":{"area":"II","group":"E","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A board quorum is a majority of the fixed number of directors, and action needs a majority of those present."}},{"i":"REG-II-E-0020","t":"Copper Kettle LLC is a member-managed limited liability company governed by the Uniform Limited Liability Company Act (2006). Its operating agreement says nothing about voting. It has three members: Ana, Ben and Cal. Ana and Ben want to change the LLC's coffee supplier, which is in the ordinary course, over Cal's objection. Ana and Ben also want to amend the operating agreement to admit an investor as a new member, again over Cal's objection. Which statement is most accurate?","mc":{"s":"Copper Kettle LLC is a member-managed limited liability company governed by the Uniform Limited Liability Company Act (2006). Its operating agreement says nothing about voting. It has three members: Ana, Ben and Cal. Ana and Ben want to change the LLC's coffee supplier, which is in the ordinary course, over Cal's objection. Ana and Ben also want to amend the operating agreement to admit an investor as a new member, again over Cal's objection. Which statement is most accurate?","d":"","o":["Ana and Ben may decide both matters, because a majority of the members controls every decision of a member-managed LLC.","Both matters require the consent of all three members, because any change of business practice needs unanimity.","Ana and Ben may decide the supplier change only if together they hold a majority of the profits interests, and the amendment needs the same majority.","Ana and Ben may decide the supplier change by a majority of the members, but the amendment requires all the members."],"a":4,"cite":"ULLCA (2006, amended 2013) §407(b)(3), (b)(4)","rat":"In a member-managed LLC, a difference on an ordinary-course matter may be decided by a majority of the members.","ex":["An amendment of the operating agreement requires all the members' consent.","Ordinary-course differences can be decided by a majority of the members.","The voting rule is a majority of the members, and an amendment needs all members regardless of profits interests.","In a member-managed LLC, a difference on an ordinary-course matter may be decided by a majority of the members. An act outside the ordinary course, and an amendment of the operating agreement, require the consent of all the members."],"wt":["concept","concept","concept",""],"tags":{"area":"II","group":"E","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"In a member-managed LLC, ordinary matters need a majority of members, but amending the operating agreement needs all members."}},{"i":"REG-II-E-0021","t":"Dax and Eve are the only members of Roan Studio LLC, a member-managed company governed by the Uniform Limited Liability Company Act (2006). The operating agreement does not change the statutory duties. Dax made a business decision that lost money after he failed to compare two suppliers, which was careless but not grossly negligent or reckless. Eve, without telling Dax, ran a competing studio while Roan Studio was operating. Which statement is most accurate?","mc":{"s":"Dax and Eve are the only members of Roan Studio LLC, a member-managed company governed by the Uniform Limited Liability Company Act (2006). The operating agreement does not change the statutory duties. Dax made a business decision that lost money after he failed to compare two suppliers, which was careless but not grossly negligent or reckless. Eve, without telling Dax, ran a competing studio while Roan Studio was operating. Which statement is most accurate?","d":"","o":["Dax breached the duty of care by ordinary negligence, and Eve did not breach any duty because she may pursue her own interest.","Both Dax and Eve breached the duty of care, because each caused harm to the company.","Dax did not breach the duty of care, which reaches only gross negligence, and Eve breached loyalty by competing.","Neither Dax nor Eve breached any duty, because members of an LLC owe fiduciary duties only to creditors."],"a":3,"cite":"ULLCA (2006, amended 2013) §409(a), (b)(3), (c)","rat":"The duty of care for members is to refrain from grossly negligent or reckless conduct, intentional misconduct or knowing violation of law.","ex":["Ordinary negligence does not breach the duty of care, and the general permission to further one's own interest does not override the specific bar on competing.","Harm alone does not breach the duty of care, and Eve's conduct is a loyalty issue.","The duty of care for members is to refrain from grossly negligent or reckless conduct, intentional misconduct or knowing violation of law. The duty of loyalty includes refraining from competing with the company before dissolution.","In a member-managed LLC members owe duties of loyalty and care to the company and the other members."],"wt":["concept","concept","","concept"],"tags":{"area":"II","group":"E","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"In a member-managed LLC, the duty of care reaches only gross negligence, and usurping company opportunity breaches loyalty."}},{"i":"REG-II-E-0022","t":"Luis is one of three members of Orbit LLC, governed by the Uniform Limited Liability Company Act (2006). Pratt holds a $60,000 judgment against Luis and obtains a charging order against Luis's transferable interest. Later Pratt shows that distributions will not pay the judgment within a reasonable time, and the court forecloses the lien. Pratt buys the transferable interest at the foreclosure sale. Which statement is most accurate about Pratt's rights?","mc":{"s":"Luis is one of three members of Orbit LLC, governed by the Uniform Limited Liability Company Act (2006). Pratt holds a $60,000 judgment against Luis and obtains a charging order against Luis's transferable interest. Later Pratt shows that distributions will not pay the judgment within a reasonable time, and the court forecloses the lien. Pratt buys the transferable interest at the foreclosure sale. Which statement is most accurate about Pratt's rights?","d":"","o":["Pratt becomes a member with full voting rights, because buying at foreclosure transfers all of the debtor's membership rights.","Pratt may compel Orbit LLC to sell its assets and pay the judgment, because a judgment lien reaches company property.","Pratt may take Luis's place as manager if the operating agreement is silent on the transfer of management rights.","Pratt is entitled to the distributions that would have gone to Luis but does not become a member and has no management rights."],"a":4,"cite":"ULLCA (2006, amended 2013) §503(a), (c)","rat":"A charging order and the purchaser at a foreclosure sale obtain only the transferable interest, which gives the right to distributions.","ex":["The foreclosure purchaser obtains only the transferable interest and does not become a member.","The lien reaches the debtor's transferable interest, not the company's property.","A transferee has no right to participate in management, whether or not the operating agreement addresses the point.","A charging order and the purchaser at a foreclosure sale obtain only the transferable interest, which gives the right to distributions. The purchaser does not become a member."],"wt":["concept","concept","concept",""],"tags":{"area":"II","group":"E","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"A charging order gives the judgment creditor only the debtor member's distributions, not membership or management rights."}}]};
window.PAIRS=[];
